DROP TABLE IF EXISTS `casedocument`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `casedocument` (
  `id` int NOT NULL AUTO_INCREMENT,
  `case_id` int DEFAULT NULL,
  `document_name` varchar(2500)  DEFAULT NULL,
  `document_category` int DEFAULT NULL,
  `document_type` int DEFAULT NULL,
  `issued_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `document_full_path` varchar(2500)  DEFAULT NULL,
  `document_file_name` varchar(500)  DEFAULT NULL,
  `documents_details` text ,
  `remarks` text ,
  `created_on` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int NOT NULL,
  `customercode` varchar(200)  DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_case_id` (`case_id`)
) ENGINE=InnoDB ;
/*!40101 SET character_set_client = @saved_cs_client */;

