--
-- Table structure for table `customercase_qa`
--

DROP TABLE IF EXISTS `customercase_qa`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customercase_qa` (
  `id` int NOT NULL AUTO_INCREMENT,
  `case_id` int NOT NULL,
  `client_id` int NOT NULL,
  `qa_status` int NOT NULL DEFAULT '0' COMMENT '0=NotReviewed,1=Pending,2=Approved,3=Rejected,4=Reopened',
  `qa_outcome` varchar(50)  DEFAULT NULL,
  `qa_reason_code` varchar(100)  DEFAULT NULL,
  `qa_reviewer_id` int DEFAULT NULL,
  `qa_reviewer_name` varchar(255)  DEFAULT NULL,
  `qa_reviewed_on` datetime DEFAULT NULL,
  `qa_comments` text ,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int DEFAULT NULL,
  `created_on` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int DEFAULT NULL,
  `updated_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_case_id` (`case_id`),
  KEY `idx_client_qa_status` (`client_id`,`qa_status`),
  KEY `idx_active_case` (`case_id`,`is_active`)
) ENGINE=InnoDB ;
/*!40101 SET character_set_client = @saved_cs_client */;

