--
-- Table structure for table `customermaster`
--

DROP TABLE IF EXISTS `customermaster`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customermaster` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cust_ref_id` varchar(50)  NOT NULL,
  `fname` varchar(255)  DEFAULT NULL,
  `mname` varchar(255)  DEFAULT NULL,
  `lname` varchar(255)  DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `nationality` varchar(250)  DEFAULT NULL,
  `cust_type` enum('I','C','S','B','V')  NOT NULL DEFAULT 'I',
  `cust_id_type` varchar(250)  DEFAULT NULL,
  `cust_id_number` varchar(250)  DEFAULT NULL,
  `mobile` varchar(50)  DEFAULT NULL,
  `batch_id` int NOT NULL DEFAULT '0',
  `is_deleted` smallint NOT NULL DEFAULT '0',
  `status` smallint NOT NULL DEFAULT '0',
  `created_by` int NOT NULL,
  `created_on` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int DEFAULT NULL,
  `updated_on` datetime DEFAULT CURRENT_TIMESTAMP,
  `customer_final_risk_score` varchar(15)  DEFAULT NULL,
  `customer_screen_match_score` int DEFAULT NULL,
  `whitelisted_for_screening` enum('NO','YES')  DEFAULT 'NO',
  `Client_Id` int DEFAULT NULL,
  `passport_expiry` varchar(45)  DEFAULT NULL,
  `customer_type` varchar(45)  DEFAULT NULL,
  `group_entity_of` varchar(45)  DEFAULT NULL,
  `designation` varchar(200)  DEFAULT NULL,
  `emirates_id` varchar(45)  DEFAULT NULL,
  `emirates_id_expiry` varchar(45)  DEFAULT NULL,
  `company_code` varchar(250)  DEFAULT NULL,
  `tradelicense` varchar(250)  DEFAULT NULL,
  `type` varchar(200)  DEFAULT NULL,
  `profession` varchar(200)  DEFAULT NULL,
  `mode_of_payment` varchar(200)  DEFAULT NULL,
  `delivery_channel` varchar(200)  DEFAULT NULL,
  `residence_status` varchar(200)  DEFAULT NULL,
  `product_name` varchar(200)  DEFAULT NULL,
  `bussiness_type` varchar(200)  DEFAULT NULL,
  `legal_status` varchar(200)  DEFAULT NULL,
  `cif_number` varchar(200)  DEFAULT NULL,
  `parent_id` varchar(200)  DEFAULT NULL,
  `screeningoption` varchar(200)  DEFAULT NULL,
  `id_issue_date` date DEFAULT NULL,
  `id_expiry_date` date DEFAULT NULL,
  `residence` varchar(200)  DEFAULT NULL,
  `employer` varchar(200)  DEFAULT NULL,
  `goldenvisa` varchar(100)  DEFAULT NULL,
  `employerindustry` varchar(200)  DEFAULT NULL,
  `employersector` varchar(200)  DEFAULT NULL,
  `sowsofcountry` varchar(200)  DEFAULT NULL,
  `tradelicenseauthority` varchar(200)  DEFAULT NULL,
  `tradelicensesector` varchar(200)  DEFAULT NULL,
  `countryparty` varchar(200)  DEFAULT NULL,
  `productvalue` varchar(200)  DEFAULT NULL,
  `productrefno` varchar(200)  DEFAULT NULL,
  `share` int DEFAULT NULL,
  `counterypartyname` varchar(200)  DEFAULT NULL,
  `relationship` varchar(200)  DEFAULT NULL,
  `flagtype` varchar(200)  DEFAULT NULL,
  `dateofwhitelisting` datetime DEFAULT NULL,
  `PassportId` varchar(255)  DEFAULT NULL,
  `PassportIssueDate` date DEFAULT NULL,
  `PassportExpiryDate` date DEFAULT NULL,
  `EmiratesIdNumber` varchar(255)  DEFAULT NULL,
  `EmiratesIdIssueDate` date DEFAULT NULL,
  `EmiratesIdExpiryDate` date DEFAULT NULL,
  `is_duplicate` int DEFAULT '0',
  `version` int DEFAULT '1',
  `group_id` varchar(100)  DEFAULT NULL,
  `group_risk` varchar(50)  DEFAULT NULL,
  `replaceflag` int DEFAULT '0',
  `updatereason` varchar(500)  DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_UNIQUE` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=67 ;
/*!40101 SET character_set_client = @saved_cs_client */;

