    DECLARE s1_char CHAR;

    DECLARE cv0, cv1 VARBINARY(256);
    SET s1_len = CHAR_LENGTH(s1), s2_len = CHAR_LENGTH(s2), cv1 = 0x00, i = 1, j = 1, c = 0, cost = 0;
    IF s1 = s2 THEN
        RETURN 0;
    ELSEIF s1_len = 0 THEN
        RETURN s2_len;
    ELSEIF s2_len = 0 THEN
        RETURN s1_len;
    ELSE
    WHILE j <= s2_len DO
        SET cv1 = CONCAT(cv1, UNHEX(LPAD(HEX(j), 2, '0'))), j = j + 1;
    END WHILE;
    WHILE i <= s1_len DO
        SET s1_char = SUBSTRING(s1, i, 1), cv0 = UNHEX(LPAD(HEX(i), 2, '0')), j = 1, c = i;
    WHILE j <= s2_len DO
        SET cost = IF(s1_char = SUBSTRING(s2, j, 1), 0, 1);

        SET c_temp = CONV(HEX(SUBSTRING(cv1, j, 1)), 16, 10) + cost;
        SET c = c + 1;
        IF c > c_temp THEN SET c = c_temp; END IF;
        SET c_temp = CONV(HEX(SUBSTRING(cv1, j+1, 1)), 16, 10) + 1;
        IF c > c_temp THEN SET c = c_temp; END IF;
        SET cv0 = CONCAT(cv0, UNHEX(LPAD(HEX(c), 2, '0'))), j = j + 1;
    END WHILE;
        SET cv1 = cv0, i = i + 1;
    END WHILE;
    END IF;
    RETURN c;
END ;;
DELIMITER ;
