DELIMITER ;;
CREATE  FUNCTION `normalize_name`(p_name VARCHAR(500)) RETURNS varchar(500) CHARSET utf8mb4
    DETERMINISTIC
BEGIN
    DECLARE v_word1 VARCHAR(500) DEFAULT '';
    DECLARE v_word2 VARCHAR(500) DEFAULT '';
    DECLARE v_word3 VARCHAR(500) DEFAULT '';
    DECLARE v_word4 VARCHAR(500) DEFAULT '';
    DECLARE v_word5 VARCHAR(500) DEFAULT '';
    DECLARE v_word6 VARCHAR(500) DEFAULT '';
    DECLARE v_swap  VARCHAR(500) DEFAULT '';
    DECLARE v_remaining VARCHAR(500);
    DECLARE v_pos       INT;
    DECLARE v_count     INT DEFAULT 0;
    DECLARE v_sorted    VARCHAR(500);
    SET v_remaining = TRIM(REGEXP_REPLACE(p_name, '\\s+', ' '));
    WHILE LOCATE(' ', v_remaining) > 0 AND v_count < 5 DO
        SET v_pos       = LOCATE(' ', v_remaining);
        SET v_count     = v_count + 1;
        CASE v_count
            WHEN 1 THEN SET v_word1 = LOWER(SUBSTRING(v_remaining, 1, v_pos - 1));
            WHEN 2 THEN SET v_word2 = LOWER(SUBSTRING(v_remaining, 1, v_pos - 1));
            WHEN 3 THEN SET v_word3 = LOWER(SUBSTRING(v_remaining, 1, v_pos - 1));
            WHEN 4 THEN SET v_word4 = LOWER(SUBSTRING(v_remaining, 1, v_pos - 1));
            WHEN 5 THEN SET v_word5 = LOWER(SUBSTRING(v_remaining, 1, v_pos - 1));
            ELSE BEGIN END;
        END CASE;
        SET v_remaining = SUBSTRING(v_remaining, v_pos + 1);
    END WHILE;
    IF v_remaining != '' THEN
        SET v_count = v_count + 1;
        CASE v_count
            WHEN 1 THEN SET v_word1 = LOWER(v_remaining);
            WHEN 2 THEN SET v_word2 = LOWER(v_remaining);
            WHEN 3 THEN SET v_word3 = LOWER(v_remaining);
            WHEN 4 THEN SET v_word4 = LOWER(v_remaining);
            WHEN 5 THEN SET v_word5 = LOWER(v_remaining);
            WHEN 6 THEN SET v_word6 = LOWER(v_remaining);
            ELSE BEGIN END;
        END CASE;
    END IF;
    IF (v_word1 > v_word2 OR v_word1 = '') AND v_word2 != '' THEN SET v_swap = v_word1; SET v_word1 = v_word2; SET v_word2 = v_swap; END IF;
    IF (v_word1 > v_word3 OR v_word1 = '') AND v_word3 != '' THEN SET v_swap = v_word1; SET v_word1 = v_word3; SET v_word3 = v_swap; END IF;
    IF (v_word1 > v_word4 OR v_word1 = '') AND v_word4 != '' THEN SET v_swap = v_word1; SET v_word1 = v_word4; SET v_word4 = v_swap; END IF;
    IF (v_word1 > v_word5 OR v_word1 = '') AND v_word5 != '' THEN SET v_swap = v_word1; SET v_word1 = v_word5; SET v_word5 = v_swap; END IF;
    IF (v_word1 > v_word6 OR v_word1 = '') AND v_word6 != '' THEN SET v_swap = v_word1; SET v_word1 = v_word6; SET v_word6 = v_swap; END IF;
    IF (v_word2 > v_word3 OR v_word2 = '') AND v_word3 != '' THEN SET v_swap = v_word2; SET v_word2 = v_word3; SET v_word3 = v_swap; END IF;
    IF (v_word2 > v_word4 OR v_word2 = '') AND v_word4 != '' THEN SET v_swap = v_word2; SET v_word2 = v_word4; SET v_word4 = v_swap; END IF;
    IF (v_word2 > v_word5 OR v_word2 = '') AND v_word5 != '' THEN SET v_swap = v_word2; SET v_word2 = v_word5; SET v_word5 = v_swap; END IF;
    IF (v_word2 > v_word6 OR v_word2 = '') AND v_word6 != '' THEN SET v_swap = v_word2; SET v_word2 = v_word6; SET v_word6 = v_swap; END IF;
    IF (v_word3 > v_word4 OR v_word3 = '') AND v_word4 != '' THEN SET v_swap = v_word3; SET v_word3 = v_word4; SET v_word4 = v_swap; END IF;
    IF (v_word3 > v_word5 OR v_word3 = '') AND v_word5 != '' THEN SET v_swap = v_word3; SET v_word3 = v_word5; SET v_word5 = v_swap; END IF;
    IF (v_word3 > v_word6 OR v_word3 = '') AND v_word6 != '' THEN SET v_swap = v_word3; SET v_word3 = v_word6; SET v_word6 = v_swap; END IF;
    IF (v_word4 > v_word5 OR v_word4 = '') AND v_word5 != '' THEN SET v_swap = v_word4; SET v_word4 = v_word5; SET v_word5 = v_swap; END IF;
    IF (v_word4 > v_word6 OR v_word4 = '') AND v_word6 != '' THEN SET v_swap = v_word4; SET v_word4 = v_word6; SET v_word6 = v_swap; END IF;
    IF (v_word5 > v_word6 OR v_word5 = '') AND v_word6 != '' THEN SET v_swap = v_word5; SET v_word5 = v_word6; SET v_word6 = v_swap; END IF;
    SET v_sorted = v_word1;
    IF v_word2 != '' THEN SET v_sorted = CONCAT(v_sorted, ' ', v_word2); END IF;
    IF v_word3 != '' THEN SET v_sorted = CONCAT(v_sorted, ' ', v_word3); END IF;
    IF v_word4 != '' THEN SET v_sorted = CONCAT(v_sorted, ' ', v_word4); END IF;
    IF v_word5 != '' THEN SET v_sorted = CONCAT(v_sorted, ' ', v_word5); END IF;
    IF v_word6 != '' THEN SET v_sorted = CONCAT(v_sorted, ' ', v_word6); END IF;
    RETURN v_sorted;
END ;;
DELIMITER ;
