CREATE  PROCEDURE `del_client`(
IN p_clientId INT,
IN p_isActive INT,
IN p_updatedBy INT
)
BEGIN
UPDATE `Client_master`
SET
`is_active` = p_isActive,
`Updated_By` = p_updatedBy,
`Updated_On`= NOW()
WHERE
	`Client_Id`= p_clientId;
END ;;
