DELIMITER ;;
CREATE  PROCEDURE `GetAllCompletedCases`( IN `p_userid` INT,
    IN c_from DATE,
    IN c_to DATE,
    IN cust_type VARCHAR(10))
BEGIN
DECLARE filter_to_date DATETIME;
DECLARE filter_from_date DATETIME;
SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
SET filter_from_date = DATE_ADD(c_from, INTERVAL 0 DAY);
IF (cust_type != '' AND cust_type != 0) THEN
    SELECT
        `ca`.`id` AS `id`,
        `cu`.`cust_ref_id` AS `customer_master_id`,
        IFNULL(`cu`.`fname`, '') AS `fname`,
        IFNULL(`cu`.`mname`, '') AS `mname`,
        IFNULL(`cu`.`lname`, '') AS `lname`,
        `cu`.`dob` AS `dob`,
        `cu`.`cust_ref_id` AS `cust_id`,
        IFNULL(`cu`.`nationality`, '') AS `nationality`,
        IFNULL(`ca`.`comments`, '') AS `comments`,
        IFNULL(`ca`.`risk_score`, 0) AS `risk_score`,
        IFNULL(`ca`.`match_score`, 0) AS `match_score`,
        `cu`.`batch_id` AS `batch_id`,
        IFNULL(`cu`.`mobile`, '') AS `mobile`,
        `cu`.`cust_type` AS `cust_type`,
        IFNULL(`cu`.`cust_id_type`, '') AS `customer_id_type`,
        IFNULL(`cu`.`cust_id_number`, '') AS `customer_id_number`,
        `ca`.`status` AS `status`,
        CASE cc.status
            WHEN 0 THEN CONCAT('Pending(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 1 THEN CONCAT('Assigned(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 2 THEN CONCAT('Approved(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 3 THEN CONCAT('Rejected(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 4 THEN CONCAT('Closed(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 5 THEN CONCAT('Auto Approved(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 6 THEN CONCAT('Pending Case Created from Daily Scheduler(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            ELSE '-'
        END AS 'CaseStatus',
        IFNULL(`ca`.`source`, '') AS `source`,
        IFNULL(`ca`.`match_category`, '') AS `match_category`,
        IFNULL(`ca`.`match_type`, '') AS `match_type`,
        `ca`.`created_by` AS `created_by`,
        `ca`.`created_on` AS `created_on`,
        `ca`.`updated_by` AS `updated_by`,
        `ca`.`updated_on` AS `updated_on`,
        IFNULL(`ca`.`source_unique_id`, '') AS `source_unique_id`,
        `ca`.`is_deleted` AS `is_deleted`,
        (SELECT CONCAT(IFNULL(`fname`, ''), ' ', IFNULL(`lname`, '')) FROM `user` `u` WHERE `u`.`id` = `ca`.`created_by`) AS `created_user`,
        IFNULL(`ca`.`is_matched`, 0) AS `is_matched`,IFNULL(cu.company_code,'N/A') AS `company_code`,
        IFNULL(cu.tradelicense,'N/A') AS tradelicense
    FROM
        customercase ca
            INNER JOIN
        customermaster cu ON cu.id = ca.cust_master_id
            INNER JOIN
        `user` `user` ON (`user`.`Client_Id` = `ca`.`Client_Id`)
    WHERE
            `cu`.`is_deleted` = 0
            AND `ca`.`is_deleted` = 0
            AND (`ca`.`status` = 2 OR ca.status = 3)
            AND ca.created_on >= filter_from_date AND ca.created_on <= filter_to_date
            AND cu.cust_type = cust_type
            AND `user`.`id` = p_userid
            And cu.type in ('Individual','Corporate')
    ORDER BY `ca`.`created_on` DESC;
ELSE
SELECT
        `ca`.`id` AS `id`,
        `cu`.`cust_ref_id` AS `customer_master_id`,
        IFNULL(`cu`.`fname`, '') AS `fname`,
        IFNULL(`cu`.`mname`, '') AS `mname`,
        IFNULL(`cu`.`lname`, '') AS `lname`,
        `cu`.`dob` AS `dob`,
        `cu`.`cust_ref_id` AS `cust_id`,
        IFNULL(`cu`.`nationality`, '') AS `nationality`,
        IFNULL(`ca`.`comments`, '') AS `comments`,
        IFNULL(`ca`.`risk_score`, 0) AS `risk_score`,
        IFNULL(`ca`.`match_score`, 0) AS `match_score`,
        `cu`.`batch_id` AS `batch_id`,
        IFNULL(`cu`.`mobile`, '') AS `mobile`,
        `cu`.`cust_type` AS `cust_type`,
        IFNULL(`cu`.`cust_id_type`, '') AS `customer_id_type`,
        IFNULL(`cu`.`cust_id_number`, '') AS `customer_id_number`,
        `ca`.`status` AS `status`,
         CASE ca.status
            WHEN 0 THEN CONCAT('Pending(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 1 THEN CONCAT('Assigned(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 2 THEN CONCAT('Approved(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 3 THEN CONCAT('Rejected(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 4 THEN CONCAT('Closed(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 5 THEN CONCAT('Auto Approved(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            WHEN 6 THEN CONCAT('Pending Case Created from Daily Scheduler(', IFNULL(ca.SOURCE, 'OTHER'), ')')
            ELSE '-'
        END AS 'CaseStatus',
        IFNULL(`ca`.`source`, '') AS `source`,
        IFNULL(`ca`.`match_category`, '') AS `match_category`,
        IFNULL(`ca`.`match_type`, '') AS `match_type`,
        `ca`.`created_by` AS `created_by`,
        `ca`.`created_on` AS `created_on`,
        `ca`.`updated_by` AS `updated_by`,
        `ca`.`updated_on` AS `updated_on`,
        IFNULL(`ca`.`source_unique_id`, '') AS `source_unique_id`,
        `ca`.`is_deleted` AS `is_deleted`,
        (SELECT CONCAT(IFNULL(`fname`, ''), ' ', IFNULL(`lname`, '')) FROM `user` `u` WHERE `u`.`id` = `ca`.`created_by`) AS `created_user`,
        IFNULL(`ca`.`is_matched`, 0) AS `is_matched`,
        IFNULL(cu.company_code,'N/A') AS `company_code`,
        IFNULL(cu.tradelicense,'N/A') AS `tradelicense`
    FROM
        customercase ca
            INNER JOIN
        customermaster cu ON cu.id = ca.cust_master_id
            INNER JOIN
        `user` `user` ON (`user`.`Client_Id` = `ca`.`Client_Id`)
    WHERE
            `cu`.`is_deleted` = 0
            AND `ca`.`is_deleted` = 0
            AND (`ca`.`status` = 2 OR ca.status = 3)
               AND ca.created_on >= filter_from_date AND ca.created_on <= filter_to_date
            AND `user`.`id` = p_userid and  cu.type in ('Individual','Corporate')
    ORDER BY `ca`.`created_on` DESC;
END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
