CREATE  PROCEDURE `GetCaseByRefId`( IN p_custRefId VARCHAR(10))
BEGIN
		SELECT cm.cust_ref_id ,
		cc.cust_master_id,
		cm.id, cm.fname, cm.mname, cm.lname,
		cm.dob, cc.threshold,
		cm.dob, cm.nationality ,
		cc.gender,
		cc.birthyear ,cc.match_type
		FROM customermaster cm JOIN customercase cc
		ON cm.cust_ref_id = cc.cust_id
		WHERE cust_ref_id= p_custRefId;
	END ;;
