DELIMITER ;;
CREATE  PROCEDURE `get_all_authorised_user`(
IN p_func_code VARCHAR(100),
IN p_module_code VARCHAR(100),
IN p_clientId INT
)
BEGIN
SELECT DISTINCT u.id, u.fname, u.lname FROM  USER u
INNER JOIN usergroup ug ON u.user_group_id=ug.id
INNER JOIN usergroupright ugr ON ugr.user_group_id=ug.id
				INNER JOIN module m ON ugr.module_id=m.id
				INNER JOIN functionality f ON ugr.func_id=f.id AND f.module_id = m.id
				WHERE  m.`code`=p_module_code
				AND f.`code`=p_func_code AND u.client_id = p_clientId;
END ;;
