CREATE  PROCEDURE `get_all_clients_admin`()
BEGIN
    SELECT
        c.Client_Id AS Client_Id,
        c.Client_Name AS Client_Name,
        c.Prefix AS Prefix,
        c.C6Username AS C6Username,
        c.C6Threshold AS C6Threshold,
        c.Threshold AS Threshold,
        c.is_active AS is_active,
        c.ApplicationStartDate AS ApplicationStartDate,
        c.ApplicationEndDate AS ApplicationEndDate,
        c.searchcount AS SearchCount,
        c.catogory_value AS Complem,
        c.Created_On AS CreatedOn,

        (SELECT COUNT(*) FROM user u WHERE u.Client_Id = c.Client_Id AND u.is_deleted = 0) AS UserCount,
        (SELECT COUNT(*) FROM customercase cc WHERE cc.Client_Id = c.Client_Id) AS UsageCount
    FROM client_master c
    ORDER BY c.Client_Name ASC;
END ;;
