CREATE  PROCEDURE `get_all_client_search_count`(
    IN c_from DATE,
    IN c_to DATE,
    IN c_clientId INT
    )
BEGIN
	DECLARE filter_to_date DATETIME;
    SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
    SELECT
        count(*) as search_count
    FROM
        customercase cc
        INNER JOIN customermaster cu ON cu.id = cc.cust_master_id
         WHERE cc.created_on >= c_from
        AND cc.created_on <= filter_to_date
		AND cc.Client_Id=c_clientId;
	END ;;
DELIMITER ;
