CREATE  PROCEDURE `get_all_countrymaster`(IN p_clientId INT)
BEGIN
	SELECT
		id,
		'' AS lov_risk_catogory,
		'' AS lov_risk_catogory_code,
		'-1' AS lov_type_id,
		'Country' AS lov_type_name,
		NAME AS lov_risk_data,
		RiskRating AS lov_risk_score,
		FATFRISKRating AS Over_ride_Score,
		'1' AS active_yn,
		created_on AS date_created,
		updated_on AS date_updated
	FROM
		country WHERE Client_Id IS NULL OR Client_Id = p_clientId;
END ;;
