CREATE  PROCEDURE `get_all_customercase`(
    IN `p_userid` INT,
    IN c_from DATE,
    IN c_to DATE,
    IN cust_type VARCHAR(10),
    In p_matchfrom int,
    In p_matchto int,
    In p_createdBy int,
    IN c_status INT,
    In p_riskLevel Varchar(200),
    In p_clientId int,
      In p_includingDuplicate Varchar(100)

)
BEGIN
DECLARE filter_to_date DATETIME;
DECLARE filter_from_date DATETIME;
SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
SET filter_from_date = DATE_ADD(c_from, INTERVAL 0 DAY);
IF (cust_type != '0') THEN
    SELECT
        `ca`.`id` AS `id`,
        `cu`.`id` AS `customer_master_id`,
        IFNULL(`cu`.`fname`, '') AS `fname`,
        IFNULL(`cu`.`mname`, '') AS `mname`,
        IFNULL(`cu`.`lname`, '') AS `lname`,
        `cu`.`dob` AS `dob`,
        `cu`.`cust_ref_id` AS `cust_id`,
        IFNULL(`cu`.`nationality`, '') AS `nationality`,
        IFNULL(`ca`.`comments`, '') AS `comments`,
        IFNULL(`ca`.`risk_score`, 0) AS `risk_score`,
        IFNULL(`ca`.`match_score`, 0) AS `match_score`,
        `cu`.`batch_id` AS `batch_id`,
        IFNULL(`cu`.`mobile`, '') AS `mobile`,
        `cu`.`cust_type` AS `cust_type`,
        IFNULL(`cu`.`cust_id_type`, '') AS `customer_id_type`,
        IFNULL(`cu`.`cust_id_number`, '') AS `customer_id_number`,
        `ca`.`status` AS `status`,
     CASE
    WHEN cu.type IN ('Individual','Corporate') THEN
        CONCAT(
            CASE ca.status
                WHEN 0 THEN 'Pending'
                WHEN 1 THEN 'WhiteList'
                WHEN 2 THEN 'Approved'
                WHEN 3 THEN 'Rejected'
                WHEN 4 THEN 'Pending with Senior Management'
                WHEN 5 THEN 'Auto'
                WHEN 6 THEN 'Pending Daily Scheduler'
                WHEN 7 THEN 'OnHold'
                ELSE '-'
            END,

            CASE
                WHEN (
                    SELECT COUNT(*)
                    FROM customermaster sh_cu
                    INNER JOIN customercase sh
                        ON sh.cust_master_id = sh_cu.id
                       AND sh.is_deleted = 0
                    WHERE sh_cu.company_code = cu.cust_ref_id
                     AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                ) > 0
                THEN CONCAT(
                    ' | Shareholders: Total ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                         AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Auto ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 5
                           AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Approved ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 2
                           AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Pending ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status IN (0,6)
                           AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Rejected ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 3
                           AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', OnHold ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 7
                           AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Whitelist ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 1
                           AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    )
                )
                ELSE ''
            END
        )
END AS 'CaseStatus',
        IFNULL(`ca`.`source`, '') AS `source`,
        IFNULL(`ca`.`match_category`, '') AS `match_category`,
        IFNULL(`ca`.`match_type`, '') AS `match_type`,
        `ca`.`created_by` AS `created_by`,
        `ca`.`created_on` AS `created_on`,
        `ca`.`updated_by` AS `updated_by`,
        `ca`.`updated_on` AS `updated_on`,
        IFNULL(`ca`.`source_unique_id`, '') AS `source_unique_id`,
        `ca`.`is_deleted` AS `is_deleted`,
        (SELECT CONCAT(IFNULL(`fname`, ''), ' ', IFNULL(`lname`, '')) FROM `user` `u` WHERE `u`.`id` = `ca`.`created_by`) AS `created_user`,
        IFNULL(`ca`.`is_matched`, 0) AS `is_matched`,IFNULL(cu.company_code,'N/A') AS `company_code`,
        IFNULL(cu.tradelicense,'N/A') AS tradelicense,
        `ca`.`case_change_status` AS case_change_status,
        `cu`.type AS type,
        `cu`.is_duplicate as is_duplicate,
        `cu`.version as version,
        `cu`.group_id AS group_id,
     `cu`.group_risk AS group_risk,
     `cu`.replaceflag as replaceflag,
     `cu`.updatereason AS updatereason,
            (SELECT tri.final_risk_score FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1 ) AS individual_risk_score,
    (SELECT trc.final_risk_score FROM transaction_risk_corporate trc  WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1 ) AS corporate_risk_score,
    (SELECT tri.risk_score_sum FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1 ) AS individual_risk_sum,
    (SELECT trc.risk_sum FROM transaction_risk_corporate trc  WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1 ) AS corporate_risk_sum,
        (SELECT tri.riskoverride FROM transaction_risk_individual tri  WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1 ) AS individual_risk_override,
    (SELECT trc.riskoverride FROM transaction_risk_corporate trc  WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1 ) AS corporate_risk_override
    FROM
        customercase ca
            INNER JOIN
        customermaster cu ON cu.id = ca.cust_master_id
    WHERE
            `cu`.`is_deleted` = 0
            AND `ca`.`is_deleted` = 0
            AND ca.created_on >= filter_from_date AND ca.created_on <= filter_to_date
            AND cu.cust_type = cust_type
            AND ca.Client_id=p_clientId
            AND ca.created_by LIKE IF(p_createdBy IS NULL OR p_createdBy = 0, '%', p_createdBy)
            AND (
				  p_matchfrom IS NULL
				  OR p_matchto IS NULL
				  OR ca.match_score BETWEEN p_matchfrom AND p_matchto
			)
            AND ca.status LIKE IF(c_status IS NULL OR c_status = 10, '%', c_status)
            AND (
            p_riskLevel IS NULL OR p_riskLevel = ''
            OR (p_riskLevel = 'Unclassified' AND (
                (cu.type = 'Individual' AND (SELECT tri.final_risk_score FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1) IS NULL)
                OR (cu.type = 'Corporate' AND (SELECT trc.final_risk_score FROM transaction_risk_corporate trc WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1) IS NULL)
            ))
            OR (cu.type = 'Individual' AND (SELECT tri.final_risk_score FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1) = p_riskLevel)
            OR (cu.type = 'Corporate' AND (SELECT trc.final_risk_score FROM transaction_risk_corporate trc WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1) = p_riskLevel)
        )

           AND cu.type IN ('Individual','Corporate')
  AND (
    (
        ca.status IN (0,5,6,7,4)
    )
    OR EXISTS (
        SELECT 1
        FROM customermaster sh_cu
        INNER JOIN customercase sh
            ON sh.cust_master_id = sh_cu.id
           AND sh.is_deleted = 0
        WHERE sh_cu.company_code = cu.cust_ref_id
          AND sh.status NOT IN (2,3,1)
    )
)
AND (

     p_includingDuplicate = 'Yes'

    OR


    (
        p_includingDuplicate IS NULL
        OR p_includingDuplicate = ''
        OR p_includingDuplicate = "0"
        OR p_includingDuplicate = 'All'
        OR p_includingDuplicate = 'No'
    )
    AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
    )
)
       ORDER BY  ca.updated_on DESC;
ELSE
    SELECT
    ca.id AS id,
    cu.cust_ref_id AS customer_master_id,
    IFNULL(cu.fname, '') AS fname,
    IFNULL(cu.mname, '') AS mname,
    IFNULL(cu.lname, '') AS lname,
    cu.dob AS dob,
    cu.cust_ref_id AS cust_id,
    IFNULL(cu.nationality, '') AS nationality,
    IFNULL(ca.comments, '') AS comments,
    IFNULL(ca.risk_score, 0) AS risk_score,
    IFNULL(ca.match_score, 0) AS match_score,
    cu.batch_id AS batch_id,
    IFNULL(cu.mobile, '') AS mobile,
    cu.cust_type AS cust_type,
    IFNULL(cu.cust_id_type, '') AS customer_id_type,
    IFNULL(cu.cust_id_number, '') AS customer_id_number,
    ca.status AS status,
    CASE
    WHEN cu.type IN ('Individual','Corporate') THEN
        CONCAT(
            CASE ca.status
            WHEN 0 THEN 'Pending'
            WHEN 1 THEN 'WhiteList'
            WHEN 2 THEN 'Approved'
            WHEN 3 THEN 'Rejected'
            WHEN 4 THEN 'Pending with Senior Management'
            WHEN 5 THEN 'Auto'
            WHEN 6 THEN 'Pending Daily Scheduler'
            WHEN 7 THEN 'OnHold'
                ELSE '-'
            END,

            CASE
                WHEN (
                    SELECT COUNT(*)
                    FROM customermaster sh_cu
                    INNER JOIN customercase sh
                        ON sh.cust_master_id = sh_cu.id
                       AND sh.is_deleted = 0
                    WHERE sh_cu.company_code = cu.cust_ref_id
                    AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                ) > 0
                THEN CONCAT(
                    ' | Shareholders: Total ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                        AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Auto ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 5
                          AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Approved ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 2
                          AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Pending ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status IN (0,6)
                          AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Rejected ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 3
                          AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', OnHold ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 7
                          AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    ),
                    ', Whitelist ',
                    (
                        SELECT COUNT(*)
                        FROM customermaster sh_cu
                        INNER JOIN customercase sh
                            ON sh.cust_master_id = sh_cu.id
                           AND sh.is_deleted = 0
                        WHERE sh_cu.company_code = cu.cust_ref_id
                          AND sh.status = 1
                          AND sh_cu.version = (
                                  SELECT MAX(cu2.version)
                                  FROM customermaster cu2
                                  WHERE cu2.cust_ref_id = sh_cu.cust_ref_id
                            )
                    )
                )
                ELSE ''
            END
        )
END AS 'CaseStatus',
    IFNULL(ca.source, '') AS source,
    IFNULL(ca.match_category, '') AS match_category,
    IFNULL(ca.match_type, '') AS match_type,
    ca.created_by AS created_by,
    ca.created_on AS created_on,
    ca.updated_by AS updated_by,
    ca.updated_on AS updated_on,
    IFNULL(ca.source_unique_id, '') AS source_unique_id,
    ca.is_deleted AS is_deleted,
    (SELECT CONCAT(IFNULL(fname, ''), ' ', IFNULL(lname, ''))
        FROM user u WHERE u.id = ca.created_by) AS created_user,
    IFNULL(ca.is_matched, 0) AS is_matched,
    IFNULL(cu.company_code,'N/A') AS company_code,
    IFNULL(cu.tradelicense,'N/A') AS tradelicense,
    `ca`.`case_change_status` AS case_change_status,
    `cu`.type AS type,
    `cu`.is_duplicate as is_duplicate,
    `cu`.version as version,
     `cu`.group_id as group_id,
     `cu`.group_risk as group_risk,
      `cu`.replaceflag as replaceflag,
      `cu`.updatereason AS updatereason,
    (SELECT tri.final_risk_score FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1 ) AS individual_risk_score,
    (SELECT trc.final_risk_score FROM transaction_risk_corporate trc  WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1 ) AS corporate_risk_score,
    (SELECT tri.risk_score_sum FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1 ) AS individual_risk_sum,
    (SELECT trc.risk_sum FROM transaction_risk_corporate trc  WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1 ) AS corporate_risk_sum,
    (SELECT tri.riskoverride FROM transaction_risk_individual tri  WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1 ) AS individual_risk_override,
    (SELECT trc.riskoverride FROM transaction_risk_corporate trc  WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1 ) AS corporate_risk_override
FROM customercase ca
            INNER JOIN
        customermaster cu ON cu.id = ca.cust_master_id
    WHERE
            `cu`.`is_deleted` = 0
            AND `ca`.`is_deleted` = 0
               AND ca.created_on >= filter_from_date AND ca.created_on <= filter_to_date
               AND ca.Client_id=p_clientId
            AND ca.created_by LIKE IF(p_createdBy IS NULL OR p_createdBy = 0, '%', p_createdBy)
            AND (
				  p_matchfrom IS NULL
				  OR p_matchto IS NULL
				  OR ca.match_score BETWEEN p_matchfrom AND p_matchto
			)
            AND ca.status LIKE IF(c_status IS NULL OR c_status = 10, '%', c_status)
          AND (
            p_riskLevel IS NULL OR p_riskLevel = ''
            OR (p_riskLevel = 'Unclassified' AND (
                (cu.type = 'Individual' AND (SELECT tri.final_risk_score FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1) IS NULL)
                OR (cu.type = 'Corporate' AND (SELECT trc.final_risk_score FROM transaction_risk_corporate trc WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1) IS NULL)
            ))
            OR (cu.type = 'Individual' AND (SELECT tri.final_risk_score FROM transaction_risk_individual tri WHERE tri.customercode = ca.cust_id AND tri.IsDeleted = 0 AND tri.assessment_version >= 2 ORDER BY tri.dateofassessment DESC, tri.id DESC LIMIT 1) = p_riskLevel)
            OR (cu.type = 'Corporate' AND (SELECT trc.final_risk_score FROM transaction_risk_corporate trc WHERE trc.customercode = ca.cust_id AND trc.IsDeleted = 0 AND trc.assessment_version >= 2 ORDER BY trc.dateofassessment DESC, trc.id DESC LIMIT 1) = p_riskLevel)
        )

  AND cu.type IN ('Individual','Corporate')
  AND (
    (
        ca.status IN (0,5,6,7,4)
    )
    OR EXISTS (
        SELECT 1
        FROM customermaster sh_cu
        INNER JOIN customercase sh
            ON sh.cust_master_id = sh_cu.id
           AND sh.is_deleted = 0
        WHERE sh_cu.company_code = cu.cust_ref_id
          AND sh.status NOT IN (2,3,1)
    )
)
AND (

     p_includingDuplicate = 'Yes'

    OR


    (
        p_includingDuplicate IS NULL
        OR p_includingDuplicate = ''
        OR p_includingDuplicate = "0"
        OR p_includingDuplicate = 'All'
        OR p_includingDuplicate = 'No'
    )
    AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
    )
)
   ORDER BY  ca.updated_on DESC;
END IF;
END ;;
