/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_all_customercase_report_by_expiry`(
IN c_from DATE,
    IN c_to DATE,
    IN c_user INT,
    IN c_status INT,
    IN c_clientId INT,
    IN cust_type VARCHAR(45),
    IN c_updated_by_id INT,
    IN c_nomatch INT,
    IN c_tdomesticpep INT,
    IN c_tforeignpep INT,
    IN  c_tadversemedia INT,
    IN c_pdomesticpep INT,
    IN c_pforeignpep INT,
    IN c_padversemedia INT,
    IN c_expirystartdate DATE,
    IN c_expiryenddate DATE,
    IN c_documentstatus VARCHAR(20)
    )
BEGIN
  DECLARE filter_to_date DATETIME;
    SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
   IF(c_documentstatus != '7')
  THEN
SELECT
    cc.created_on,
    cust_ref_id AS cust_id,
        CASE cu.cust_type
            WHEN 'I' THEN 'Individual'
            WHEN 'C' THEN 'Corporate'
            WHEN 'S' THEN 'Share Holder'
            ELSE ''
        END AS customer_id_type,
CONCAT_WS(' ', cu.fname,
                   CASE WHEN cu.mname NOT IN ('', ' ') THEN cu.mname END,
                   cu.lname) AS 'customer_name',
        CASE cc.status
            WHEN 0 THEN CONCAT('Pending(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 1 THEN CONCAT('Assigned(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 2 THEN CONCAT('Approved(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 3 THEN CONCAT('Rejected(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 4 THEN CONCAT('Closed(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 5 THEN CONCAT('Auto Approved(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 6 THEN CONCAT('Pending Case Created from Daily Scheduler(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            ELSE '-'
        END AS 'status',
           CONCAT(IFNULL(cru.fname, ''), ' ', IFNULL(cru.lname, '')) AS 'created_by',
        CONCAT(IFNULL(upu.fname, ''), ' ', IFNULL(upu.lname, '')) AS 'updated_by',
        cc.match_score AS 'match',
        cc.is_matched,
        cc.updated_on,
        IFNULL(cu.company_code,'N/A') AS company_code,
        IFNULL(cu.tradelicense,'N/A') AS tradelicense,
         IFNULL(cu.nationality,'N/A') AS nationality,
         IFNULL(cu.dob,'N/A') AS dob
    FROM
        customercase cc
       JOIN customermaster cu ON  cc.cust_master_id = cu.id
        LEFT JOIN USER cru ON cc.created_by = cru.id
        LEFT JOIN USER upu ON cc.updated_by = upu.id Left JOIN casedocument cd on cc.id=cd.case_id
    WHERE
      cu.is_deleted = 0
    AND cc.is_deleted = 0
       AND cc.created_on >= c_from
    AND cc.created_on <= filter_to_date
        AND cc.Client_Id = c_clientId
        AND cu.cust_type LIKE IF(cust_type IS NULL OR cust_type = '' OR cust_type = '0','%', cust_type)
        AND cc.status LIKE IF(c_status IS NULL OR c_status = 10, '%', c_status)
        AND cc.created_by LIKE IF(c_user IS NULL OR c_user = 0, '%', c_user)
        AND cc.updated_by LIKE IF(c_updated_by_id IS NULL OR c_updated_by_id = 0, '%', c_updated_by_id)
        AND cc.no_match LIKE IF(c_nomatch IS NULL OR c_nomatch = 0, '%', c_nomatch)
        AND cc.true_dometic_pep LIKE IF(c_tdomesticpep IS NULL OR c_tdomesticpep = 0, '%', c_tdomesticpep)
        AND cc.true_foreign_pep LIKE IF(c_tforeignpep IS NULL OR c_tforeignpep = 0, '%', c_tforeignpep)
        AND cc.true_adversemedia LIKE IF(c_tadversemedia IS NULL OR c_tadversemedia = 0, '%', c_tadversemedia)
        AND cc.partial_domestic_pep LIKE IF(c_pdomesticpep IS NULL OR c_pdomesticpep = 0, '%', c_pdomesticpep)
        AND cc.partial_foreign_pep LIKE IF(c_pforeignpep IS NULL OR c_pforeignpep = 0, '%', c_pforeignpep)
         AND cc.partial_adversemedia LIKE IF(c_padversemedia IS NULL OR c_padversemedia = 0, '%', c_padversemedia)
         AND (cd.expiry_date BETWEEN c_expirystartdate AND c_expiryenddate)
    ORDER BY
        cc.created_on DESC;
     else
	SELECT
    cc.created_on,
    cust_ref_id AS cust_id,
        CASE cu.cust_type
            WHEN 'I' THEN 'Individual'
            WHEN 'C' THEN 'Corporate'
            WHEN 'S' THEN 'Share Holder'
            ELSE ''
        END AS customer_id_type,
CONCAT_WS(' ', cu.fname,
                   CASE WHEN cu.mname NOT IN ('', ' ') THEN cu.mname END,
                   cu.lname) AS 'customer_name',
        CASE cc.status
            WHEN 0 THEN CONCAT('Pending(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 1 THEN CONCAT('Assigned(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 2 THEN CONCAT('Approved(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 3 THEN CONCAT('Rejected(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 4 THEN CONCAT('Closed(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 5 THEN CONCAT('Auto Approved(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            WHEN 6 THEN CONCAT('Pending Case Created from Daily Scheduler(', IFNULL(CC.SOURCE, 'OTHER'), ')')
            ELSE '-'
        END AS 'status',
           CONCAT(IFNULL(cru.fname, ''), ' ', IFNULL(cru.lname, '')) AS 'created_by',
        CONCAT(IFNULL(upu.fname, ''), ' ', IFNULL(upu.lname, '')) AS 'updated_by',
        cc.match_score AS 'match',
        cc.is_matched,
        cc.updated_on,
        IFNULL(cu.company_code,'N/A') AS company_code,
        IFNULL(cu.tradelicense,'N/A') AS tradelicense,
         IFNULL(cu.nationality,'N/A') AS nationality,
         IFNULL(cu.dob,'N/A') AS dob
    FROM
        customercase cc
       JOIN customermaster cu ON  cc.cust_master_id = cu.id
        LEFT JOIN USER cru ON cc.created_by = cru.id
        LEFT JOIN USER upu ON cc.updated_by = upu.id LEFT JOIN casedocument cd ON cc.id=cd.case_id
    WHERE
      cu.is_deleted = 0
    AND cc.is_deleted = 0
       AND cc.created_on >= c_from
    AND cc.created_on <= filter_to_date
        AND cc.Client_Id = c_clientId
        AND cu.cust_type LIKE IF(cust_type IS NULL OR cust_type = '' OR cust_type = '0','%', cust_type)
        AND cc.status LIKE IF(c_status IS NULL OR c_status = 10, '%', c_status)
        AND cc.created_by LIKE IF(c_user IS NULL OR c_user = 0, '%', c_user)
        AND cc.updated_by LIKE IF(c_updated_by_id IS NULL OR c_updated_by_id = 0, '%', c_updated_by_id)
        AND cc.no_match LIKE IF(c_nomatch IS NULL OR c_nomatch = 0, '%', c_nomatch)
        AND cc.true_dometic_pep LIKE IF(c_tdomesticpep IS NULL OR c_tdomesticpep = 0, '%', c_tdomesticpep)
        AND cc.true_foreign_pep LIKE IF(c_tforeignpep IS NULL OR c_tforeignpep = 0, '%', c_tforeignpep)
        AND cc.true_adversemedia LIKE IF(c_tadversemedia IS NULL OR c_tadversemedia = 0, '%', c_tadversemedia)
        AND cc.partial_domestic_pep LIKE IF(c_pdomesticpep IS NULL OR c_pdomesticpep = 0, '%', c_pdomesticpep)
        AND cc.partial_foreign_pep LIKE IF(c_pforeignpep IS NULL OR c_pforeignpep = 0, '%', c_pforeignpep)
         AND cc.partial_adversemedia LIKE IF(c_padversemedia IS NULL OR c_padversemedia = 0, '%', c_padversemedia)
         AND cd.expiry_date >  c_expiryenddate
    ORDER BY
        cc.created_on DESC;
     end if;
	END ;;
DELIMITER ;
