DELIMITER ;;
CREATE  PROCEDURE `get_all_customercase_version`(IN p_id varchar(200))
BEGIN
select
	cc.`id`,
	cm.`fname`,
	cm.`mname`,
	cm.`lname`,
    cm.`cust_type`,
	cm.`dob`,
	cc.`cust_id`,
	cm.`nationality`,
	cc.`comments`,
	cc.`risk_score`,
	cc.`match_score`,
	cm.`batch_id`,
	cm.`mobile`,
	cm.`cust_id_type` AS `customer_id_type`,
	cm.`cust_id_number` AS `customer_id_number`,
	cc.`status`,
    CASE cc.status
       WHEN 0 THEN CONCAT('Pending')
        WHEN 1 THEN CONCAT('White List')
        WHEN 2 THEN CONCAT('Approved')
        WHEN 3 THEN CONCAT('Rejected')
        WHEN 4 THEN CONCAT('Pending with Senior Management')
        WHEN 5 THEN CONCAT('Auto')
        WHEN 6 THEN CONCAT('Pending Case Created from Daily Scheduler')
        WHEN 7 THEN CONCAT('On Hold')
        ELSE '-'
        END
         AS 'CaseStatus',
	cc.`source`,
	cc.`match_category`,
	cc.`match_type`,
	cc.`created_by`,
	cc.`created_on`,
	concat(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) as `updated_user`,us.user_name as `created_user`,
	cc.`updated_on`,
    cc.source_unique_id,
	cc.`is_deleted`,
    cc.`cust_master_id`,
    cm.whitelisted_for_screening,
       tri.final_risk_score AS 'individual_risk_score',
    trc.final_risk_score AS 'corporate_risk_score',
    cc.no_match,
    cc.true_dometic_pep,
    cc.true_foreign_pep,
    cc.true_adversemedia,
    cc.partial_domestic_pep,
    cc.partial_foreign_pep,
    cc.partial_adversemedia,
    cc.true_uae_un_sanction,
    cc.true_other_sanction,
    cc.gender,
    cm.type,
    cm.parent_id,
    cm.flagtype,
    cm.is_duplicate,
    cm.version
FROM customercase cc
JOIN customermaster cm
    ON cc.cust_master_id = cm.id

LEFT JOIN user u ON cc.updated_by = u.id
LEFT JOIN user us ON cm.created_by = us.id

LEFT JOIN (
    SELECT *
    FROM transaction_risk_individual t1
    WHERE t1.id = (
        SELECT t2.id
        FROM transaction_risk_individual t2
        WHERE t2.customercode = t1.customercode
        ORDER BY t2.dateofassessment DESC, t2.id DESC
        LIMIT 1
    )
) tri ON cc.cust_id = tri.customercode

LEFT JOIN (
    SELECT *
    FROM transaction_risk_corporate t1
    WHERE t1.id = (
        SELECT t2.id
        FROM transaction_risk_corporate t2
        WHERE t2.customercode = t1.customercode
        ORDER BY t2.dateofassessment DESC, t2.id DESC
        LIMIT 1
    )
) trc ON cc.cust_id = trc.customercode
where cm.`cust_ref_id`=p_id;
END ;;
DELIMITER ;
