CREATE  PROCEDURE `get_all_customercatogory`()
BEGIN
SELECT
	`id`,
	`code`,
	`name`,
	`description`,
	`is_active`,
    `score`
FROM
	`customercategory` where is_active=1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
