DELIMITER ;;
CREATE  PROCEDURE `get_all_customer_by_Type_Search`( IN p_customerType VARCHAR(10))
BEGIN
IF p_customerType = 'C' THEN
SELECT DISTINCT (cust_ref_id),
CONCAT(IFNULL(cu.fname,''), ' ', IFNULL(cu.mname,''), ' ', IFNULL(cu.lname,'')) AS customer_name,
dob,
nationality,
cust_type
FROM customermaster CU JOIN
corporate_kyc ck
ON cu.cust_ref_id = ck.customer_id
WHERE
cust_type ='C'  AND
is_deleted = 0 AND cust_ref_id NOT LIKE '% V%' ORDER BY cu.created_on DESC;
ELSEIF p_customerType = 'I' THEN
SELECT cust_ref_id,
CONCAT(IFNULL(cu.fname,''), ' ', IFNULL(cu.mname,''), ' ', IFNULL(cu.lname,'')) AS customer_name,
dob,
nationality,
cust_type
FROM customermaster CU JOIN
individual_kyc ik
ON cu.cust_ref_id = ik.customer_id
WHERE
cust_type ='I'  AND
is_deleted = 0 AND cust_ref_id NOT LIKE '% V%' ORDER BY cu.created_on DESC;
END IF;
END ;;
DELIMITER ;
