/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_all_Dataset_Update_logs`( IN c_from DATE,
    IN c_to DATE,IN c_datasets VARCHAR(10))
BEGIN
DECLARE filter_to_date DATETIME;
DECLARE filter_from_date DATETIME;
SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
SET filter_from_date = DATE_ADD(c_from, INTERVAL 0 DAY);
SELECT
    id,
    datasets,
    delta,
    cumulative,
    individualdelta,
    corporatedelta,
    createdon
FROM UploadDatasetsLOGS
WHERE
    DATE(createdon) >= filter_from_date
    AND DATE(createdon) <= filter_to_date
    AND (
         c_datasets IS NULL
        OR c_datasets = ''
        OR datasets LIKE CONCAT('%', c_datasets, '%')
    );
END ;;
DELIMITER ;
