DELIMITER ;;
CREATE  PROCEDURE `get_all_etllogs_by_date`(
IN p_added_on_from varchar(20),
IN p_added_on_to varchar(20))
BEGIN
SELECT
    `etl`.`id` AS `id`,
    `etl`.`file_name` AS `file_name`,
    `etl`.`file_full_path` AS `file_full_path`,
	`etl`.`total_rows` AS `total_rows`,
    `etl`.`rows_recorded` AS `rows_recorded`,
    `etl`.`added_by` AS `added_by`,
     CONCAT(`u`.`fname`," ", `u`.`lname`) AS `added_by_name`,
    `etl`.`added_on` AS `added_on`
FROM `etlbatch` `etl`
INNER JOIN `user` `u`
	ON `u`.`id`=`etl`.`added_by`
WHERE  CONVERT(`etl`.`added_on`,DATE)  between p_added_on_from and p_added_on_to order by `etl`.`added_on`;
END ;;
DELIMITER ;
