DELIMITER ;;
CREATE  PROCEDURE `get_all_functionality`(
IN `p_clientId` INT)
BEGIN
SELECT
	`func`.`id`,
	`func`.`module_id`,

    (SELECT `mod`.`code` FROM `module` `mod` WHERE `mod`.`id` = `func`.`module_id`) AS `module_code`,
    (SELECT `modu`.`name` FROM `module` `modu` WHERE `modu`.`id` = `func`.`module_id`) AS `module_name`,
	`func`.`code`,
	`func`.`name`,
    `func`.`allowanonymous`
FROM
	`functionality` `func`
    inner join client_right_master crm on crm.Client_Id = p_clientId
    inner join menu_master m on m.Menu_Id = crm.Menu_Id and func.Menu_Id = m.Menu_Id
WHERE
     `func`.`allowanonymous` = 0 and `func`.`module_id` in (SELECT `mod`.`id` FROM `module` `mod` WHERE `mod`.`allowanonymous` = 0) and m.is_active = 1
ORDER BY `name`;
END ;;
DELIMITER ;
