/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_all_pending_transaction_screening_case`(IN  `c_from` DATETIME,
IN `c_to` DATETIME,
IN `p_clientId` INT)
BEGIN
 DECLARE filter_to_date DATETIME;
  SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
SELECT tranrefno, createdon , COUNT(*) AS CaseCount,
SUM(CASE WHEN STATUS = 0 THEN 1 ELSE 0 END) AS Pending,
SUM(CASE WHEN STATUS IN (5,2) THEN 1 ELSE 0 END) AS Approved,
SUM(CASE WHEN STATUS = 3  THEN 1 ELSE 0 END) AS Rejected
FROM transactionscreen
WHERE Client_Id =p_clientId
GROUP BY tranrefno, DATE(createdon)
HAVING Pending !=0   AND Rejected = 0

ORDER BY tranrefno;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
