CREATE  PROCEDURE `get_all_riskconfiguration`(
IN p_riskcategory_id varchar(2),
IN p_lov_type_category_id int,
IN p_lov_type_id int,
IN p_lov_select int
)
BEGIN
CASE
 WHEN
	p_lov_select=1 THEN
		select id,lov_type_category from lovtypecategory where lov_risk_category_code=p_riskcategory_id and active_yn=1;
  WHEN
	p_lov_select=2 THEN
		select lov_type_id,lov_type_name from lovtypemaster_backup where lov_type_category_id=p_lov_type_category_id and active_yn=1;
	WHEN
    p_lov_select=3 THEN
		select lov_risk_data,lov_risk_score,Over_ride_Score from lovmaster where lov_type_id=p_lov_type_id and active_yn=1;
end case;
END ;;
DELIMITER ;
