CREATE  PROCEDURE `get_all_sanctionfordashboard`(IN clientid INT, IN cType VARCHAR(500))
BEGIN
if(cType='I')
then
SELECT cc.cust_id,
CONCAT(IFNULL(cm.fname, ''), ' ', IFNULL(cm.mname,''), ' ', IFNULL(cm.lname,''))AS `created_user`,cm.cust_type , cc.created_on,IFNULL(cm.nationality,'Empty') As nationality
 FROM `customermaster`  cm JOIN customercase cc ON cm.id= cc.cust_master_id WHERE cm.Client_id= clientid and cm.cust_type='I'
  ORDER BY  cc.created_on DESC LIMIT 10;
else
	SELECT cc.cust_id,
CONCAT(IFNULL(cm.fname, ''), ' ', IFNULL(cm.mname,''), ' ', IFNULL(cm.lname,''))AS `created_user`,cm.cust_type ,
cc.created_on, IFNULL(cm.nationality,'Empty') As nationality
 FROM `customermaster`  cm JOIN customercase cc ON cm.id= cc.cust_master_id WHERE cm.Client_id= clientid AND cm.cust_type='C'
 ORDER BY  cc.created_on DESC LIMIT 10;
	END IF;
	END ;;
DELIMITER ;
