CREATE  PROCEDURE `get_all_Screening_database_logs`(In c_from date,In c_to date)
BEGIN
 DECLARE filter_to_date DATETIME;
    SET filter_to_date = DATE_ADD(c_to, INTERVAL 1 DAY);
SELECT `id`,
   `individual`,
    `corporate`,
    `deleted`,
    DATE(`updateddate`) AS `updateddate`
FROM `screening_database_logs` where updateddate >= c_from
    AND updateddate <= filter_to_date order by id desc;
	END ;;
