DELIMITER ;;
CREATE  PROCEDURE `get_all_user_password_logs`(
in `p_datef` DATE,
in `p_datet` DATE
)
BEGIN
DECLARE p_datefrom DATETIME;
DECLARE p_dateto DATETIME;
SET p_datefrom = p_datef;
SET p_dateto = DATE_ADD(p_datet, INTERVAL 1 DAY);
	SELECT 	a.UserId, a.UserName, concat(b.fname, ' ', b.lname) as FullName , b.user_name as UpdatedBy, a.UpdatedOn as UpdatedOn
	FROM user_password_history a
	inner join user b on b.id = a.UpdatedBy
	WHERE  a.UpdatedOn
    BETWEEN p_datefrom AND p_dateto
	ORDER BY a.UpdatedOn DESC;
END ;;
DELIMITER ;
