DELIMITER ;;
CREATE  PROCEDURE `get_authenticated_user`(
IN p_user_name VARCHAR(200), IN p_password VARCHAR(200)
,IN p_clientName VARCHAR(200)
)
BEGIN
SELECT
	u.`id`,
	u.`fname`,
	u.`lname`,
	u.`emp_code`,
	ud.`email`,
	u.`user_name`,
	u.`password`,
	u.`remarks`,
	u.`designation_id`,
	u.`department_id`,
	u.`user_group_id`,
	u.`branch_id`,
	u.`country_id`,
	u.`identity_type_id`,
	u.`is_active`,
	u.`is_deleted`,
	u.`is_blocked`,
	u.`created_by`,
	u.`created_on`,
	u.`updated_by`,
	u.`updated_on`,
    u.`Client_Id`
FROM `user` u
INNER JOIN client_master cm ON cm.Client_Id = u.Client_Id JOIN userdetail ud ON u.id=ud.user_id
WHERE u.`user_name`=p_user_name AND u.`password`=MD5(p_password)
AND u.`is_blocked` != 1 AND cm.is_active = 1 AND u.is_deleted != 1 AND cm.`Client_Name` = p_clientName;
END ;;
DELIMITER ;
