CREATE  PROCEDURE `get_authenticated_user_by_otp`(
IN p_user_name VARCHAR(200),
IN p_otp INT,
IN p_clientId INT)
BEGIN
SELECT
	`id`,
	`fname`,
	`lname`,
	`emp_code`,
	`user_name`,
	`password`,
	`remarks`,
	`designation_id`,
	`department_id`,
	`user_group_id`,
	`branch_id`,
	`country_id`,
	`identity_type_id`,
	`is_active`,
	`is_deleted`,
	`is_blocked`,
	`created_by`,
	`created_on`,
	`updated_by`,
	`updated_on`
FROM `user` WHERE `user_name`=p_user_name AND `otp`=p_otp and Client_Id = p_clientId;
END ;;
