DELIMITER ;;
CREATE  PROCEDURE `get_authenticated_user_by_username`(
IN p_user_name VARCHAR(200),
IN p_clientName VARCHAR(200))
BEGIN
SELECT
	`user`.`id`,
	`fname`,
	`lname`,
	`emp_code`,
	`user_name`,
	`password`,
	`remarks`,
	`designation_id`,
	`department_id`,
	`user_group_id`,
	`branch_id`,
	`country_id`,
	`identity_type_id`,
	`user`.`is_active`,
	`user`.`is_deleted`,
	`user`.`is_blocked`,
	`user`.`created_by`,
	`user`.`created_on`,
	`user`.`updated_by`,
	`user`.`updated_on`,
	`email`,
    `user`.Client_Id
FROM `user`
left JOIN `USERdetail` ON `USERdetail`.user_id= `user`.id
inner join client_master cm on cm.Client_Id = user.Client_Id
WHERE `user`.`user_name`=p_user_name and cm.`Client_Name` = p_clientName;
END ;;
