CREATE  PROCEDURE `get_bulkrisk_lovtype_id`(
IN p_nationality VARCHAR(50),
IN p_FATF VARCHAR(50),
IN p_profession VARCHAR(50),
IN p_residence VARCHAR(200),
IN p_product VARCHAR(100),
IN p_delivery VARCHAR(500),
IN p_sourceoffund VARCHAR(5),
IN p_modeofpayment VARCHAR(100),
IN p_screened VARCHAR(100),
IN p_moreproduct VARCHAR(100),
IN p_isadveres VARCHAR(100),
IN p_customertype VARCHAR(100),
IN p_clientId INT,
IN p_nat1 VARCHAR(50),
IN p_nat2 VARCHAR(50),
IN p_nat3 VARCHAR(50)
)
BEGIN
DECLARE natId INT;
DECLARE nat1Id INT;
DECLARE nat2Id INT;
DECLARE nat3Id INT;
DECLARE FATFId INT;
DECLARE profId INT;
DECLARE resId INT;
DECLARE prodId INT;
DECLARE delId INT;
DECLARE souId INT;
DECLARE modId INT;
DECLARE screId INT;
DECLARE moreprodId INT;
DECLARE  adverseId INT;
IF p_profession != ''
THEN
	SET profId = (SELECT * FROM
(SELECT lov_type_id FROM lovmaster WHERE  lov_risk_data=p_profession  AND active_yn = 1 AND lov_risk_catogory = p_customertype AND   Client_Id = p_clientId
                  UNION
                  SELECT lov_type_id FROM lovmaster WHERE lov_risk_data=p_profession AND active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId
) A LIMIT 1);
ELSE
	SET profId = 0;
END IF;
IF p_nationality != ''
THEN
	SET natId = (SELECT lov_type_id FROM lovmaster WHERE  lov_risk_data=p_nationality AND  active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId  LIMIT 1);
 ELSE
	SET natId = 0;
END IF;
IF p_nationality != ''
THEN
	SET natId = (SELECT lov_type_id FROM lovmaster WHERE  lov_risk_data=p_nationality AND  active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId  LIMIT 1);
 ELSE
	SET natId = 0;
END IF;
IF p_residence != ''
THEN
	SET resId = (SELECT lov_type_id FROM lovmaster WHERE  lov_risk_data= p_residence  AND active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET resId = 0;
END IF;
IF p_customertype='Corporate'
THEN
IF p_product != ''
THEN
	SET prodId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name = 'Product' AND  lov_risk_data = p_product AND active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET prodId = 0;
END IF;
ELSE
IF p_product != ''
THEN
	SET prodId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name = 'Product, Service & Activity' AND  lov_risk_data = p_product AND active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET prodId = 0;
END IF;
END IF;
IF p_delivery != ''
THEN
	SET delId = (SELECT lov_type_id FROM lovmaster WHERE  lov_risk_data= p_delivery  AND active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET delId = 0;
END IF;
IF p_modeofpayment != ''
THEN
	SET modId = (SELECT lov_type_id FROM lovmaster WHERE  lov_risk_data = p_modeofpayment AND active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET modId = 0;
END IF;
IF p_moreproduct != ''
THEN
	SET moreprodId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name ='If More Than One Product(Put The Riskiest Product)'AND   lov_risk_data = p_moreproduct AND  active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET moreprodId = 0;
END IF;
IF p_customertype='Corporate'
THEN
IF p_screened != ''
THEN
	SET screId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name='Is there any PEP match on the Owner/Partners/BOD and Senior Management names?' AND   lov_risk_data = p_screened AND  active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET screId = 0;
END IF;
IF p_isadveres != ''
THEN
	SET adverseId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name='Is there a sanction match on the company, Owner/Partners/BOD, Senior Management, group company, holding company or related company names?' AND   lov_risk_data = p_isadveres AND  active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET adverseId = 0;
END IF;
ELSE
IF p_screened != ''
THEN
	SET screId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name='Is The Customer A Pep Or Related Close Associate Of Pep?' AND   lov_risk_data = p_screened AND  active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET screId = 0;
END IF;
IF p_isadveres != ''
THEN
	SET adverseId = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name='Does Ubo/Customer Name/Beneficiary Name Feature In Any Sanction List Or In Adverse Media?' AND   lov_risk_data = p_isadveres AND  active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET adverseId = 0;
END IF;
END IF;
IF p_FATF != ''
THEN
	SET FATFId = (SELECT lov_type_id FROM lovmaster WHERE  lov_type_name ='Does the company have any subsidiary, affiliate, branch or group/holding company in FATF listed high risk monitored jurisdiction?' AND   lov_risk_data = p_FATF AND  active_yn = 1  AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId LIMIT 1 );
ELSE
	SET FATFId = 0;
END IF;
IF p_nat1 != ''
THEN
	SET nat1Id = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name = 'Nationality- Partner 1'   AND lov_risk_data=p_nat1 AND  active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId  LIMIT 1);
 ELSE
	SET nat1Id = 0;
END IF;
IF p_nat2 != ''
THEN
	SET nat2Id = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name = 'Nationality- Partner 2'   AND lov_risk_data=p_nat2 AND  active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId  LIMIT 1);
 ELSE
	SET nat2Id = 0;
END IF;
IF p_nat3 != ''
THEN
	SET nat3Id = (SELECT lov_type_id FROM lovmaster WHERE lov_type_name = 'Nationality- Partner 3'   AND lov_risk_data=p_nat3 AND  active_yn = 1 AND lov_risk_catogory = p_customertype   AND Client_Id = p_clientId  LIMIT 1);
 ELSE
	SET nat3Id = 0;
END IF;
 SELECT CONCAT(profId,'Ø',natId,'Ø',resId,'Ø',prodId,'Ø',delId,'Ø',modId, 'Ø',moreprodId,'Ø',screId,'Ø',adverseId,'Ø',FATFId,'Ø',nat1Id,'Ø',nat2Id,'Ø',nat3Id);
END ;;
DELIMITER ;
