CREATE  PROCEDURE `get_cases_for_documentUpload`( IN p_customerType VARCHAR(10))
BEGIN
IF ( p_customerType = 'I') THEN
    SELECT
       cc.id
    FROM
        customercase cc
        JOIN customermaster cm
        ON cc.cust_id = cm.cust_ref_id
        WHERE cc.match_category = 'INDIVIDUAL'
        AND cc.id NOT IN (SELECT case_id FROM casedocument )
        AND cc.cust_id NOT IN (SELECT customer_id FROM individual_kyc)
        AND cm.customer_type IS NULL
        ORDER BY cc.created_on DESC;
ELSEIF(p_customerType = 'C') THEN
	SELECT
       id
    FROM
        customercase cc
        WHERE cc.match_category = 'CORPORATE'
        AND cc.id NOT IN (SELECT case_id FROM casedocument )
        AND cc.cust_id NOT IN (SELECT customer_id FROM corporate_kyc)
        ORDER BY created_on DESC;
END IF;
END ;;
DELIMITER ;
