DELIMITER ;;
CREATE  PROCEDURE `get_cases_list`( IN p_caseId INT ,IN p_name VARCHAR(10),IN p_customerType VARCHAR(10))
BEGIN
IF p_customerType='I'   THEN
	IF p_caseId !=0 THEN
		SELECT * FROM `customermaster` WHERE id IN (SELECT cust_master_id FROM  customercase WHERE id=p_caseId) AND cust_type = 'I' ;
	ELSEIF (p_name!=NULL OR p_name!='') THEN
		SELECT * FROM `customermaster` WHERE cust_type = 'I'
		AND LOWER( CONCAT(IFNULL(fname,''), ' ', IFNULL(mname,''), ' ', IFNULL(lname,''))) LIKE  LOWER( CONCAT('%',p_name,'%') );
	END IF;
ELSEIF p_customerType='C' THEN
	IF p_caseId !=0 THEN
		SELECT * FROM `customermaster` WHERE id IN  (SELECT cust_master_id FROM  customercase WHERE id=p_caseId) AND cust_type = 'C' ;
	ELSEIF (p_name!=NULL OR p_name!='') THEN
		SELECT * FROM `customermaster` WHERE cust_type = 'C'
		AND LOWER( CONCAT(IFNULL(fname,''), ' ', IFNULL(mname,''), ' ', IFNULL(lname,''))) LIKE  LOWER( CONCAT('%',p_name,'%') );
	END IF;
END IF;
END ;;
DELIMITER ;
