/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_case_comments_by_case_id`(IN p_case_id INT)
BEGIN
SELECT
	`cc`.`id`,
	`cc`.`case_id`,
	`cc`.`comment`,
	`cc`.`created_on`,
	`cc`.`created_by`,
    `cc`.`comment_type`,
    (SELECT CONCAT(`fname`, ' ', `lname`) FROM `user` `u` WHERE `u`.`id`=`cc`.`created_by`) AS `created_user`,
    (CASE
		WHEN TIMESTAMPDIFF(YEAR, created_on, NOW()) > 0 THEN CONCAT(TIMESTAMPDIFF(YEAR, created_on, NOW()), ' ', 'Years ago')
        WHEN TIMESTAMPDIFF(MONTH, created_on, NOW()) > 0 THEN CONCAT(TIMESTAMPDIFF(MONTH, created_on, NOW()), ' ', 'Months ago')
        WHEN TIMESTAMPDIFF(DAY, created_on, NOW()) > 0 THEN CONCAT(TIMESTAMPDIFF(DAY, created_on, NOW()), ' ', 'Days ago')
        WHEN TIMESTAMPDIFF(HOUR, created_on, NOW()) > 0 THEN CONCAT(TIMESTAMPDIFF(HOUR, created_on, NOW()), ' ', 'Hours ago')
        WHEN TIMESTAMPDIFF(MINUTE, created_on, NOW()) > 0 THEN CONCAT(TIMESTAMPDIFF(MINUTE, created_on, NOW()), ' ', 'Minutes ago')
        ELSE CONCAT(TIMESTAMPDIFF(SECOND, created_on, NOW()), ' ', 'Seconds ago')
	END) AS `duration_in_words`
FROM
	`casecomment` `cc`
WHERE
	`cc`.`case_id`=p_case_id order by id desc;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
