CREATE  PROCEDURE `get_count_by_risk`(
IN `category_id` INT,
IN `clientid` INT
)
BEGIN
	IF (category_id = 1) THEN
			SELECT COUNT(*) as total_count,
			sum( case when final_risk_score = 'High Risk' then 1 else 0 end) as high_risk,
			sum( case when final_risk_score = 'Medium Risk' then 1 else 0 end) as medium_risk,
			sum( case when final_risk_score = 'Low Risk' then 1 else 0 end) as low_risk
			FROM transaction_risk_individual WHERE IsDeleted=0 AND Client_Id = clientid AND id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_individual   GROUP BY customercode);
	ELSEIF (category_id = 2) THEN
			SELECT COUNT(*) as total_count,
			sum( case when final_risk_score = 'High Risk' then 1 else 0 end) as high_risk,
			sum( case when final_risk_score = 'Medium Risk' then 1 else 0 end) as medium_risk,
			sum( case when final_risk_score = 'Low Risk' then 1 else 0 end) as low_risk
            FROM transaction_risk_corporate WHERE IsDeleted=0 AND Client_Id = clientid AND id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_corporate  GROUP BY customercode);
    ELSEIF (category_id = 3) THEN
			SELECT COUNT(*) as total_count,
			sum( case when final_risk_score = 'High Risk' then 1 else 0 end) as high_risk,
			sum( case when final_risk_score = 'Medium Risk' then 1 else 0 end) as medium_risk,
			sum( case when final_risk_score = 'Low Risk' then 1 else 0 end) as low_risk
            FROM transaction_risk_bank WHERE Client_Id = clientid;
    ELSE
			SELECT COUNT(*) as total_count,
			sum( case when final_risk_score = 'High Risk' then 1 else 0 end) as high_risk,
			sum( case when final_risk_score = 'Medium Risk' then 1 else 0 end) as medium_risk,
			sum( case when final_risk_score = 'Low Risk' then 1 else 0 end) as low_risk
            FROM transaction_risk_vendor WHERE Client_Id = clientid;
	END IF;
END ;;
DELIMITER ;
