CREATE  PROCEDURE `get_customercase_by_batch_id`(IN p_batch_id INT)
BEGIN
select
	`id`,
	`fname`,
	`mname`,
	`lname`,
	`dob`,
	`cust_id`,
	`nationality`,
	`comments`,
	`risk_score`,
