	`batch_id`,
	`status`,
	`source`,
	`created_by`,
	`created_on`,
	`updated_by`,
	`updated_on`,
	`is_delete`
from
customercase
where `is_delete` = 0 AND `batch_id`=p_batch_id;
END ;;
