CREATE  PROCEDURE `get_customercase_by_custid`(IN p_id Varchar(200),In p_version int)
BEGIN
SELECT
    cm.`id`,
    cm.`fname`,
    cm.`mname`,
    cm.`lname`,
    cm.`cust_type`,
    cm.`dob`,
    cc.`cust_id`,
    cm.`nationality`,
    cc.`comments`,
    cc.`risk_score`,
    cc.`match_score`,
    cm.`batch_id`,
    cm.`mobile`,
    cm.`cust_id_type` AS `customer_id_type`,
    cm.`cust_id_number` AS `customer_id_number`,
    cc.`status`,
    cc.`source`,
    cc.`match_category`,
    cc.`match_type`,
    cc.`client_id` AS `client_id`,
    cc.`created_by`,
    cc.`created_on`,
    CONCAT(IFNULL(u.`fname`, ''), ' ', IFNULL(u.`lname`, '')) AS `updated_user`,
    us.`user_name` AS `created_user`,
    cc.`updated_on`,
    cc.`source_unique_id`,
    cc.`is_deleted`,
    cc.`cust_master_id`,
    cm.`whitelisted_for_screening`,
    tri.`final_risk_score` AS `individual_risk_score`,
    trc.`final_risk_score` AS `corporate_risk_score`,
    cc.`no_match`,
    cc.`true_dometic_pep`,
    cc.`true_foreign_pep`,
    cc.`true_adversemedia`,
    cc.`partial_domestic_pep`,
    cc.`partial_foreign_pep`,
    cc.`partial_adversemedia`,
    cc.`true_uae_un_sanction`,
    cc.`true_other_sanction`,
    cc.`gender`,
    cm.`type`,
    cm.`cif_number`,
    cm.`mode_of_payment`,
    cm.`delivery_channel`,
    cm.`residence_status`,
    cm.`product_name`,
    cm.`bussiness_type`,
    cm.`legal_status`,
    cm.`profession`,
    cc.`threshold`,
    cm.`screeningoption`,
    cc.`case_change_status` AS `case_change_status`,
    cm.`id_issue_date`,
    cm.`id_expiry_date`,
    cm.`residence`,
    cm.`employer`,
    cm.`goldenvisa`,
    cm.`employerindustry`,
    cm.`employersector`,
    cm.`sowsofcountry`,
    cm.`tradelicenseauthority`,
    cm.`countryparty`,
    cm.`counterypartyname`,
    cm.`productvalue`,
    cm.`productrefno`,
    cm.`relationship`,
    cm.`flagtype`,
    cc.`schedulertrackerId`,
    cc.`SchedulerProcessedOn`,
    cm.`company_code`,
    cm.`version`,
    cc.`is_matched`,
    cm.`group_id`,
    cm.`group_risk`
FROM customercase cc
INNER JOIN customermaster cm
    ON cc.`cust_master_id` = cm.`id`
LEFT JOIN `user` u
    ON cc.`updated_by` = u.`id`
LEFT JOIN `user` us
    ON cm.`created_by` = us.`id`
LEFT JOIN transaction_risk_individual tri
    ON cc.`cust_id` = tri.`customercode`
LEFT JOIN transaction_risk_corporate trc
    ON cc.`cust_id` = trc.`customercode`
WHERE cm.`cust_ref_id` = p_id
  AND cm.`version` =
    CASE
        WHEN IFNULL(p_version, 0) = 0 THEN
            (
                SELECT MAX(cu2.`version`)
                FROM customermaster cu2
                WHERE cu2.`cust_ref_id` = cm.`cust_ref_id`
            )
        ELSE p_version
    END;
	END ;;
DELIMITER ;
