/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_customercase_by_match`(
	IN `c_from` DATE,
    IN `c_to` DATE,
    IN `c_is_match` INT,
    IN `c_clientId` INT
)
BEGIN
	DECLARE matchCase INT;
    DECLARE toDate DATETIME;
    SET toDate = DATE_ADD(c_to, INTERVAL 1 DAY);
	IF(c_is_match = 2) THEN
		SELECT
			cc.created_on,
			cc.cust_id,
			CASE cc.cust_type
				WHEN'I' THEN 'Individual'
                WHEN 'C' THEN 'Corporate'
                WHEN 'S' THEN 'Share Holder'
                ELSE ''
            END AS customer_id_type,
			CONCAT(IFNULL(cc.fname, ''), ' ', IFNULL(cc.mname,''), ' ', IFNULL(cc.lname,'')) AS 'customer_name',
			CASE cc.status
				WHEN 0 THEN 'Matched, Pending case'
				WHEN 1 THEN 'Assigned'
				WHEN 2 THEN 'Matched, Approved'
				WHEN 3 THEN 'Matched, Rejected'
				WHEN 5 THEN 'No match, Auto Approved'
				ELSE 'NOT FOUND'
			END AS 'match' ,
            CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) AS 'created_by'
		FROM v_customercase cc
        INNER JOIN USER u ON cc.created_by = u.id
        INNER JOIN customercase c ON c.id = cc.id
		WHERE  cc.created_on >= c_from AND cc.created_on <= toDate AND
        cc.status IN(0,2,3) AND c.Client_Id = c_clientId ORDER BY cc.created_on DESC;
	ELSEIF(c_is_match = 3) THEN
		SELECT
			cc.created_on,
			cc.cust_id,
			CASE cc.cust_type
				WHEN'I' THEN 'Individual'
                WHEN 'C' THEN 'Corporate'
                WHEN 'S' THEN 'Share Holder'
                ELSE ''
            END AS customer_id_type,
			CONCAT(IFNULL(cc.fname, ''), ' ', IFNULL(cc.mname,''), ' ', IFNULL(cc.lname,'')) AS 'customer_name',
			CASE cc.status
				WHEN 0 THEN 'Matched, Pending case'
				WHEN 1 THEN 'Assigned'
				WHEN 2 THEN 'Matched, Approved'
				WHEN 3 THEN 'Matched, Rejected'
				WHEN 5 THEN 'No match, Auto Approved'
				ELSE 'NOT FOUND'
			END AS 'match',
            CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) AS 'created_by'
		FROM v_customercase cc
        INNER JOIN USER u ON cc.created_by = u.id
        INNER JOIN customercase c ON c.id = cc.id
		WHERE  cc.created_on >= c_from AND cc.created_on <= toDate AND
        cc.status IN(5)  AND c.Client_Id = c_clientId ORDER BY cc.created_on DESC;
    ELSE
		SELECT
			cc.created_on,
			cc.cust_id,
			CASE cc.cust_type
				WHEN'I' THEN 'Individual'
                WHEN 'C' THEN 'Corporate'
                WHEN 'S' THEN 'Share Holder'
                ELSE ''
            END AS customer_id_type,
			CONCAT(IFNULL(cc.fname, ''), ' ', IFNULL(cc.mname, ''), ' ', IFNULL(cc.lname,'')) AS 'customer_name',
            CASE cc.status
				WHEN 0 THEN 'Matched, Pending case'
				WHEN 1 THEN 'Assigned'
				WHEN 2 THEN 'Matched, Approved'
				WHEN 3 THEN 'Matched, Rejected'
				WHEN 5 THEN 'No match, Auto Approved'
				ELSE 'NOT FOUND'
			END AS 'match',
                  CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) AS 'created_by'
		FROM v_customercase cc
        INNER JOIN USER u ON cc.created_by = u.id
        INNER JOIN customercase c ON c.id = cc.id
		WHERE cc.created_on >= c_from AND cc.created_on <= toDate AND c.Client_Id = c_clientId ORDER BY cc.created_on DESC;
	END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
