/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_customercase_count_by_status`(
IN `c_status` INT,
IN `c_clientid` INT
)
BEGIN
	IF (c_status < 10) THEN
		IF(c_status = 2) THEN
			SELECT COUNT(*) FROM customercase cc INNER JOIN customermaster cu ON cu.id = cc.cust_master_id WHERE cu.is_deleted = 0 AND cc.is_deleted = 0 AND (cc.status = 2 OR cc.status = 5)AND cu.Client_Id = c_clientid AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
  );
        ELSE
			IF(c_status = 0) THEN
				SELECT COUNT(*) FROM customercase cc INNER JOIN customermaster cu ON cu.id = cc.cust_master_id WHERE cu.is_deleted = 0 AND cc.is_deleted = 0 AND (cc.status = 0 OR cc.status = 6)AND cu.Client_Id = c_clientid AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
  );
	ELSE
			IF(c_status = 5) THEN
				SELECT COUNT(*) FROM customercase cc INNER JOIN customermaster cu ON cu.id = cc.cust_master_id WHERE cu.is_deleted = 0 AND cc.is_deleted = 0 AND cc.status = 5 AND cu.Client_Id = c_clientid AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
  );
			ELSE
				SELECT COUNT(*) FROM customercase cc INNER JOIN customermaster cu ON cu.id = cc.cust_master_id WHERE cu.is_deleted = 0 AND cc.is_deleted = 0 AND (cc.status = c_status)AND cu.Client_Id = c_clientid AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
  );
			END IF;
		END IF;
	  END IF;
	ELSE
		SELECT COUNT(*) FROM customercase cc INNER JOIN customermaster cu ON cu.id = cc.cust_master_id WHERE cu.is_deleted = 0 AND cc.is_deleted = 0 AND cu.Client_Id = c_clientid  AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
  );
	END IF;
END ;;
DELIMITER ;
