CREATE  PROCEDURE `get_customercase_full_details_by_cust_id`(
 IN `p_cust_id` INT
 )
BEGIN
	DECLARE case_id INT;
    DECLARE userid INT;
    DECLARE cust_code VARCHAR(250);
	IF EXISTS (SELECT MAX(id) FROM customercase WHERE cust_master_id=p_cust_id  AND `status` = 0) THEN
		SELECT MAX(id) INTO case_id FROM customercase WHERE cust_master_id=p_cust_id;
    ELSE
		BEGIN
			SELECT cust_id, created_by INTO cust_code, userid FROM customermaster WHERE id=p_cust_id;
			INSERT INTO `customercase`
			(
				cust_master_id,
				cust_id,
				created_by,
				is_deleted,
				`status`,
				`match_category`,
				`match_type`,
				created_on
			  )
			 VALUES (
				p_cust_id,
				cust_id,
				created_by,
				0,
				0,
				'',
				'',
				NOW()
			 );
			 SELECT last_insert_id() INTO case_id;
         END;
    END IF;
	SELECT
		ca.`id`,
		cu.`fname`,
		cu.`mname`,
		cu.`lname`,
		cu.`dob`,
		cu.`cust_ref_id` AS cust_id,
		cu.`nationality`,
		ca.`comments`,
		ca.`risk_score`,
		ca.`match_score`,
		cu.`batch_id`,
		cu.`mobile`,
		cu.`cust_type`,
		cu.`cust_id_number`,
		ca.`status`,
		ca.`source`,
		ca.`match_category`,
		ca.`match_type`,
		ca.`created_by`,
		ca.`created_on`,
		ca.`updated_by`,
		ca.`updated_on`,
		ca.`source_unique_id`,
		ca.`is_deleted`,
        cu.`whitelisted_for_screening`,
		ca.c6threshold,
        ca.threshold
	FROM
		customermaster cu
	INNER JOIN
		customercase ca
	ON
		ca.cust_id=cu.cust_ref_id
	WHERE
		ca.id=case_id;
END ;;
