CREATE  PROCEDURE `get_customerdetails_by_customerid`(In p_customerid varchar(500),
In p_userid int)
BEGIN
if(p_userid != 0)then
select
	cc.`id`,
	cm.`fname`,
	cm.`mname`,
	cm.`lname`,
	cm.`dob`,
	cc.`cust_id`,
	cm.`nationality`,
	cc.`comments`,
	cc.`risk_score`,
	cc.`match_score`,
	cm.`batch_id`,
	cm.`mobile`,
	cm.`cust_id_type` AS `customer_id_type`,
	cm.`cust_id_number` AS `customer_id_number`,
	cc.`status`,
	cc.`source`,
	cc.`match_category`,
	cc.`match_type`,
	cc.`created_by`,
	cc.`created_on`,
	concat(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) as `updated_user`,us.user_name as `created_user`,
	cc.`updated_on`,
    cc.source_unique_id,
	cc.`is_deleted`,
    cc.`cust_master_id`,
    cm.whitelisted_for_screening,
    cc.no_match,
    cc.true_dometic_pep,
    cc.true_foreign_pep,
    cc.true_adversemedia,
    cc.partial_domestic_pep,
    cc.partial_foreign_pep,
    cc.partial_adversemedia,
    cc.true_uae_un_sanction,
    cc.true_other_sanction
from
	customercase cc
    JOIN customermaster cm ON `cc`.`cust_id` = `cm`.`cust_ref_id`
    LEFT JOIN user u ON cc.updated_by = u.id
    left join user us on cm.created_by = us.id
where cc.`cust_id`= p_customerid and cc.created_by=p_userid;
else
SELECT
	cc.`id`,
	cm.`fname`,
	cm.`mname`,
	cm.`lname`,
	cm.`dob`,
	cc.`cust_id`,
	cm.`nationality`,
	cc.`comments`,
	cc.`risk_score`,
	cc.`match_score`,
	cm.`batch_id`,
	cm.`mobile`,
	cm.`cust_id_type` AS `customer_id_type`,
	cm.`cust_id_number` AS `customer_id_number`,
	cc.`status`,
	cc.`source`,
	cc.`match_category`,
	cc.`match_type`,
	cc.`created_by`,
	cc.`created_on`,
	CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) AS `updated_user`,us.user_name AS `created_user`,
	cc.`updated_on`,
    cc.source_unique_id,
	cc.`is_deleted`,
    cc.`cust_master_id`,
    cm.whitelisted_for_screening,
    cc.no_match,
    cc.true_dometic_pep,
    cc.true_foreign_pep,
    cc.true_adversemedia,
    cc.partial_domestic_pep,
    cc.partial_foreign_pep,
    cc.partial_adversemedia,
    cc.true_uae_un_sanction,
    cc.true_other_sanction
FROM
	customercase cc
    JOIN customermaster cm ON `cc`.`cust_id` = `cm`.`cust_ref_id`
    LEFT JOIN USER u ON cc.updated_by = u.id
    LEFT JOIN USER us ON cm.created_by = us.id
WHERE cc.`cust_id`= p_customerid;
end if;
	END ;;
DELIMITER ;
