CREATE  PROCEDURE `get_customertype_count`(In c_customertype Varchar(500),IN `c_clientid` INT)
BEGIN
	SELECT COUNT(*) FROM customercase cc INNER JOIN customermaster cu ON cu.id = cc.cust_master_id WHERE cu.is_deleted = 0 AND cc.is_deleted = 0 AND cu.cust_type=c_customertype AND cu.Client_Id = c_clientid   AND cu.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cu.cust_ref_id
  );
	END ;;
