CREATE  PROCEDURE `get_customer_by_code_from_customermasters`(
	IN p_prefix VARCHAR(15)
)
BEGIN
	SELECT
        `cu`.`id` AS `id`,
        `cu`.`id` AS `customer_master_id`,
        IFNULL(`cu`.`fname`, '') AS `fname`,
        IFNULL(`cu`.`mname`, '') AS `mname`,
        IFNULL(`cu`.`lname`, '') AS `lname`,
        DATE_FORMAT(`cu`.`dob`,'%d/%m/%Y') AS `dob`,
        `cu`.`cust_ref_id` AS `cust_id`,
        IFNULL(`cu`.`nationality`, '') AS `nationality`,
        `whitelisted_for_screening`
    FROM
        `customermaster` `cu`
		WHERE cust_ref_id LIKE CONCAT(p_prefix, '%');
END ;;
DELIMITER ;
