CREATE  PROCEDURE `get_customer_by_idorname`(IN p_id VARCHAR(10), IN p_name VARCHAR(30), IN p_CustomerType VARCHAR(10))
BEGIN
IF (p_name IS NULL AND p_id!='--EMPTY--') THEN
	SELECT `fname`,
		`mname`,
		`lname`,
		`cust_ref_id`,
		`dob`,
		`cust_type`,
		`nationality`,
		`created_by`,
		`is_deleted`,
		`mobile`,
		`cust_id_type`,
		`cust_id_number`,
		`status`,
		`batch_id`,
		`created_on`,
        `Client_Id`,
        `company_code` FROM `customermaster`
	WHERE	`cust_ref_id` LIKE CONCAT(p_id,'%' ) AND cust_type = p_CustomerType;
ELSEIF (p_id = '--EMPTY--' AND p_name IS NOT NULL)  THEN
	SELECT `fname`,
		`mname`,
		`lname`,
		`cust_ref_id`,
		`dob`,
		`cust_type`,
		`nationality`,
		`created_by`,
		`is_deleted`,
		`mobile`,
		`cust_id_type`,
		`cust_id_number`,
		`status`,
		`batch_id`,
		`created_on`,
        `Client_Id`,
        `company_code` FROM	`customermaster`
	WHERE	LOWER(`fname`) LIKE LOWER( CONCAT('%',p_name,'%') )
		OR LOWER(`mname`) LIKE LOWER(CONCAT('%',p_name,'%') )
		OR LOWER(`lname`) LIKE LOWER(CONCAT('%',p_name,'%'))  AND cust_type = p_CustomerType;
ELSE
	SELECT `fname`,
		`mname`,
		`lname`,
		`cust_ref_id`,
		`dob`,
		`cust_type`,
		`nationality`,
		`created_by`,
		`is_deleted`,
		`mobile`,
		`cust_id_type`,
		`cust_id_number`,
		`status`,
		`batch_id`,
		`created_on`,
        `Client_Id`,
        `company_code` FROM	`customermaster`
	WHERE	`cust_ref_id` LIKE CONCAT(p_id,'%' ) AND LOWER(`fname`) LIKE LOWER( CONCAT('%',p_name,'%') )
		OR LOWER(`mname`) LIKE LOWER(CONCAT('%',p_name,'%') )
		OR LOWER(`lname`) LIKE LOWER(CONCAT('%',p_name,'%'))  AND cust_type = p_CustomerType;
END IF;
END ;;
DELIMITER ;
