CREATE  PROCEDURE `get_customer_master_by_id`(IN p_id INT)
BEGIN
SELECT
`id`,
`cust_ref_id`,
        CONCAT(IFNULL(`fname`, ''), ' ', IFNULL(`mname`, ''), '', IFNULL(`lname`, '')) AS fname,
`dob`,
`nationality`,
CASE WHEN `cust_type` = 'I'
THEN 'INDIVIDUAL'
            WHEN `cust_type` = 'C'
THEN 'CORPORATE'
            WHEN `cust_type` = 'S'
THEN 'SHAREHOLDER'
            ELSE ''
END AS 'cust_type',
`cust_id_type`,
`cust_id_number`,
`mobile`,
`batch_id`,
        `status`,
`created_by`,
`created_on`,
`updated_by`,
`updated_on`,
        `customer_final_risk_score`,
        `customer_screen_match_score`,
        `whitelisted_for_screening`
FROM
customermaster
WHERE
id=p_id;
END ;;
DELIMITER ;
