CREATE  PROCEDURE `get_customer_master_by_searchterm`(IN p_searchitem VARCHAR(200),IN p_cust_type TEXT,
    IN p_clientId INT)
BEGIN
SELECT
        `cu`.`id` AS `id`,
        `cu`.`id` AS `customer_master_id`,
        IFNULL(`cu`.`fname`, '') AS `fname`,
        IFNULL(`cu`.`mname`, '') AS `mname`,
        IFNULL(`cu`.`lname`, '') AS `lname`,

        `cu`.`dob`,
        `cu`.`cust_ref_id`,
        IFNULL(`cu`.`nationality`, '') AS `nationality`,
        `whitelisted_for_screening`,
        CONCAT(`cu`.`cust_ref_id`,' - ',IFNULL(`cu`.`fname`,''),' ',IFNULL(`cu`.`mname`,''),' ',IFNULL(`cu`.`lname`,'') ) AS `FullName`
FROM
customermaster cu
WHERE cust_type = p_cust_type AND is_deleted = 0 AND Client_id = `p_clientId` AND (CONCAT(IFNULL(`cu`.`fname`,''),' ',IFNULL(`cu`.`mname`,''),' ',IFNULL(`cu`.`lname`,'') ) LIKE CONCAT('%', p_searchitem, '%') OR cust_ref_id LIKE CONCAT('%', p_searchitem, '%'));
END ;;
