DELIMITER ;;
CREATE  PROCEDURE `get_etl_dataload_report`(
            IN `p_startDate` DATE,
            IN `p_endDate` DATE,
            IN `p_matchtype` int,
            IN `p_clientId` int
        )
BEGIN
            DECLARE filter_to_date DATETIME;
            SET filter_to_date = DATE_ADD(p_endDate, INTERVAL 1 DAY);
            SELECT
                etlb.id,
                file_name,
                file_full_path,
                total_rows,
                rows_recorded,
                added_by,
                added_on,
                cc.is_matched,
                CONCAT(usr.fname, ' ', usr.lname) AS 'added_by_name'
            FROM
                etlbatch etlb
                    INNER JOIN
                customermaster cm ON etlb.id = cm.batch_id
                    INNER JOIN
                customercase cc ON `cc`.`cust_id` = `cm`.`cust_ref_id`
                    INNER JOIN
                `user` usr ON usr.id = etlb.added_by
            WHERE
                added_on >= p_startDate
                    AND added_on <= filter_to_date
                    AND cc.is_matched = (CASE
                        WHEN p_matchtype = 2 THEN 1
                        WHEN p_matchtype = 3 THEN 0
                    ELSE cc.is_matched
                END)
                    AND etlb.Client_Id = p_clientId
            GROUP BY etlb.id,cc.is_matched;
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
