DELIMITER ;;
CREATE  PROCEDURE `get_etl_dataload_report_by_batch`(
             IN `p_batchId` INT,
            IN `p_clientId` INT
)
BEGIN
            SELECT
                cc.id,
                cc.id AS `uid`,
                cm.fname,
                cm.mname,
                cm.lname,
                cm.dob,
                cc.cust_id,
                cm.nationality,
                cntry.name AS `nationality_name`,
                cc.risk_score,
                cc.match_score,
                cc.is_matched,
                cm.batch_id,
                cc.created_by,
                cc.`status`,
                cc.created_on,
                cc.`source`
            FROM
                customercase cc
                    INNER JOIN
                customermaster cm ON `cc`.`cust_id` = `cm`.`cust_ref_id`
                    LEFT JOIN
                country cntry ON cntry.id = cm.nationality
            WHERE
                  cm.batch_id = p_batchId
                    AND cc.Client_Id = p_clientId;
        END ;;
DELIMITER ;
