CREATE  PROCEDURE `get_functionality_by_id`(IN p_id INT)
BEGIN
SELECT
	`func`.`id`,
	`func`.`module_id`,
    (SELECT `mod`.`code` FROM `module` `mod` WHERE `mod`.`id` = `func`.`id`) AS `module_code`,
    (SELECT `modu`.`name` FROM `module` `modu` WHERE `modu`.`id` = `func`.`id`) AS `module_name`,
	`func`.`code`,
	`func`.`name`
FROM
	`functionality` `func`
WHERE
	`id`=p_id;
END ;;
