CREATE  PROCEDURE `get_id_by_cust_id`(IN p_id VARCHAR(25))
BEGIN

  SELECT ca.id
FROM customermaster cm
JOIN customercase ca
  ON cm.id = ca.cust_master_id
WHERE  cm.version = (
        SELECT MAX(cu2.version)
        FROM customermaster cu2
        WHERE cu2.cust_ref_id = cm.cust_ref_id
  )
AND cm.cust_ref_id = p_id;
END ;;
