DELIMITER ;;
CREATE  PROCEDURE `get_isotprequiredtoday`(in p_user_id INT)
BEGIN
DECLARE IsOtpRequired BIT;
SET IsOtpRequired=0;
    IF EXISTS
    (
        SELECT 1
        FROM user
        WHERE id = p_user_id
          AND (lastOtpVerifiedOn IS NULL
               OR CAST(lastOtpVerifiedOn AS DATE) < CAST( CURDATE() AS DATE))
    )
    then
        SET @IsOtpRequired = 1;
	else
    SET @IsOtpRequired = 0;
    END if;
    SELECT @IsOtpRequired AS IsOtpRequired;
END ;;
DELIMITER ;
