CREATE  PROCEDURE `get_kyc_corporate_details_by_CustRefId`(IN p_CustRefId VARCHAR(250))
BEGIN
SELECT cu.cust_ref_id,cu.fname,cu.mname,cu.lname,cu.nationality,cu.dob,cu.customer_type,cc.status,cc.source,cc.match_score FROM customermaster cu
inner join customercase cc on cu.cust_ref_id  =cc.cust_id
 where cust_ref_id LIKE p_CustRefId
UNION ALL
SELECT cu.cust_ref_id,cu.fname,cu.mname,cu.lname,cu.nationality,cu.dob,cu.customer_type,cc.status,cc.source,cc.match_score FROM  corporateshareholder c
LEFT JOIN customermaster cu ON c.cust_id_gen=cu.cust_ref_id
inner join customercase cc on cu.cust_ref_id  =cc.cust_id
WHERE  c.corporate_id=p_CustRefId OR cu.cust_ref_id
AND (cu.customer_type='Shareholder' OR cu.customer_type='Senior Management' OR cu.customer_type='Authorised Signatories' OR  cu.customer_type='');
END ;;
DELIMITER ;
