/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_kyc_riskconfiguration`(
IN p_risk_code VARCHAR(2),
IN p_lov_type_category_id INT,
IN p_lov_type_id INT,
IN p_lov_select INT,
IN p_clientId INT
)
BEGIN
	CASE
		WHEN p_lov_select = 1 THEN
			SELECT id ,lov_type_category FROM lovtypecategory
			WHERE active_yn=1 AND lov_risk_category_code=p_risk_code   AND (Client_Id = p_clientId) ;
		WHEN p_lov_select = 2 THEN
			SELECT id ,lov_type_name,lov_country_duplicate FROM lovtypemaster_backup
            WHERE active_yn=1 AND lov_type_category_id = p_lov_type_category_id   AND (Client_Id = p_clientId);
		WHEN p_lov_select = 3 THEN
			SELECT id,lov_risk_data,lov_risk_score,Over_ride_Score FROM lovmaster
            WHERE active_yn=1 AND lov_type_id = p_lov_type_id  AND (Client_Id = p_clientId);
	END CASE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
