DELIMITER ;;
CREATE  PROCEDURE `get_lastes_risk_version_details`(In p_customercode Varchar(200),In p_customertype varchar(100))
BEGIN
if(p_customertype ='I')
Then
SELECT `id` AS s_no,
    `customercode`,
    `customername`,
    `dateofassessment`,
    `createddate`,
    `address`,
    `Customer_nationality`,
    `risk_score_sum`,
    `final_risk_score` AS final_score,
    `risk_score_count`,
    `risk_score_before_override` AS score_before_override,
    `Client_Id`,
    `IsDeleted`,
    `created_by`,
    `assessment_version`,
    `version`,
    `remarks` FROM transaction_risk_individual where customercode=p_customercode ORDER BY assessment_version ASC
;
else
SELECT `id`AS s_no,
    `customercode`,
    `customername`,
    `dateofassessment`,
    `createddate`,
    `address`,
    `Customer_nationality`,
    `legal_status_text`,
    `legal_status`,
    `final_risk_score` as final_score,
    `risk_score_before_override` As score_before_override,
    `risk_category_type_id`,
    `risk_sum`,
    `risk_count`,
    `Client_Id`,
    `IsDeleted`,
    `created_by`,
    `assessment_version`,
    `version`,
    `remarks`
FROM transaction_risk_corporate
WHERE customercode = p_customercode
ORDER BY assessment_version ASC
;
end if;
END ;;
DELIMITER ;
