IN p_risk_code VARCHAR(2),
IN p_lov_type_category_id INT,
IN p_lov_type_id INT,
IN p_lov_select INT,
IN p_clientId INT,
IN p_version INT
)
BEGIN
CASE
	WHEN p_lov_select = 1 THEN
	    SELECT id ,lov_type_category FROM lovtypecategory
	    WHERE active_yn=1 AND lov_risk_category_code=p_risk_code  AND (Client_Id =1 or Client_Id = p_clientId) ;
	WHEN p_lov_select = 2 THEN
	    SELECT id ,lov_type_name,lov_country_duplicate FROM lovtypemaster_backup
	    WHERE active_yn=1 AND lov_type_category_id = p_lov_type_category_id  AND (Client_Id =1 or  Client_Id = p_clientId);
	WHEN p_lov_select = 3 THEN
	    SELECT id,lov_risk_data,lov_risk_score,Over_ride_Score FROM lovmaster
	    WHERE active_yn=1 AND lov_type_id = p_lov_type_id  AND (Client_Id = p_clientId);
END CASE;
END ;;
