DELIMITER ;;
CREATE  PROCEDURE `get_risk_id_by_customercode`(
    IN p_customercode VARCHAR(500),
    IN p_type         VARCHAR(200)
)
BEGIN
    IF p_type = 'I' THEN
        SELECT id
        FROM transaction_risk_individual
        WHERE customercode = p_customercode
          AND IsDeleted = 0
        ORDER BY id DESC
        LIMIT 1;
    ELSE
        SELECT id
        FROM transaction_risk_corporate
        WHERE customercode = p_customercode
          AND IsDeleted = 0
        ORDER BY id DESC
        LIMIT 1;
    END IF;
END ;;
