DELIMITER ;;
CREATE  PROCEDURE `get_risk_individual_by_cid`(IN p_id VARCHAR(500),In p_caseVersion int)
BEGIN
SELECT
		tri.*,
		LTM.lov_type_category_id,
        TSCORE.trans_risk_type_id AS lov_type_id,
		IF(LTM.lov_country_duplicate = 1, CT.name, LM.lov_risk_data) AS lov_risk_data,
		IF(LTM.lov_country_duplicate = 1, CT.RiskRating, LM.lov_risk_score) AS lov_risk_score,
		IF(LTM.lov_country_duplicate = 1, CT.FATFRISKRating, LM.Over_ride_Score) AS Over_ride_Score
	FROM
		transaction_risk_individual tri
			INNER JOIN  transaction_risk_category_type_score TSCORE ON tri.customercode = TSCORE.customer_code
			AND tri.assessment_version = TSCORE.assessment_version
			INNER JOIN
		lovtypemaster_backup LTM ON TSCORE.trans_risk_type_id = LTM.lov_type_id
			LEFT JOIN
		lovmaster LM ON LM.id = TSCORE.trans_risk_item_id
			LEFT JOIN
		country CT ON CT.id = TSCORE.trans_risk_item_id
WHERE
    	tri.IsDeleted=0 AND tri.customercode = p_id AND tri.assessment_version =
    (
        SELECT MAX(t1.assessment_version)
        FROM transaction_risk_individual t1
        WHERE t1.customercode = p_id
          AND t1.IsDeleted = 0
          AND (

                (
                    EXISTS (
                        SELECT 1
                        FROM transaction_risk_individual t2
                        WHERE t2.customercode = p_id
                          AND t2.caseversion = p_caseVersion
                          AND t2.IsDeleted = 0
                    )
                    AND t1.caseversion = p_caseVersion
                )

                OR


                (
                    NOT EXISTS (
                        SELECT 1
                        FROM transaction_risk_individual t2
                        WHERE t2.customercode = p_id
                          AND t2.caseversion = p_caseVersion
                          AND t2.IsDeleted = 0
                    )
                )
          )
    );
END ;;
DELIMITER ;
