 SELECT CONCAT(IFNULL(profId,0),'Ø',IFNULL(natId,0),'Ø',IFNULL(entId,0),'Ø',IFNULL(incorpId,0),'Ø',IFNULL(busId,0),'Ø',IFNULL(resId,0),'Ø',IFNULL(part1,0),'Ø',IFNULL(part2,0),'Ø',IFNULL(part3,0),'Ø',IFNULL(part4,0),'Ø',IFNULL(part5,0),'Ø',IFNULL(prodId,0),'Ø',IFNULL(deliveryId,0),'Ø',IFNULL(IndprodId,0),'Ø',IFNULL(InddeliveryId,0),'Ø',IFNULL(IndmodeofpaymentId,0),'Ø',IFNULL(CorpmodeofpaymentId,0),'Ø',IFNULL(InddomesticId,0),'Ø',IFNULL(CorpdomesticId,0),'Ø',IFNULL(IndforeignId,0),'Ø',IFNULL(CorpforeignId,0),'Ø',IFNULL(IndredflagsId,0),'Ø',IFNULL(corpredflagsId,0),'Ø',IFNULL(IndsanctionMatchId,0),'Ø',IFNULL(CorpsanctionMatchId,0),'Ø',IFNULL(InduaeorunscId,0),'Ø',IFNULL(CorpuaeorunscId,0),'Ø',IFNULL(CorpfatfId,0),'Ø',IFNULL(IndhighestriskproductId,0),'Ø',IFNULL(corphighestriskproductId,0),'Ø',IFNULL(IndhighnetworkindividualId,0),'Ø',IFNULL(corphighnetworkindividualId,0),'Ø',IFNULL(dualusegoodsId,0),'Ø',IFNULL(inddualusegoodsId,0),'Ø',IFNULL(moredualusegoodsId,0),'Ø',IFNULL(indmoredualusegoodsId,0));
END ;;
