CREATE  PROCEDURE `get_risk_score_all_cust_types_summary`(
	IN `c_as_on_date` DATE,
    IN `c_clientId` INT
    )
BEGIN
DECLARE To_Date DATETIME;
SET To_Date = DATE_ADD(c_as_on_date, INTERVAL 0 DAY);
SET @sql = NULL;
SELECT risk_type, sum(High_Risk_Count) as High_Risk_CountA, sum(Medium_Risk_Count) as Medium_Risk_CountA, sum(Low_Risk_Count) as Low_Risk_CountA
FROM
(
SELECT 'Individual' as risk_type,  count(final_risk_score) as High_Risk_Count,0 as Medium_Risk_Count,0 as Low_Risk_Count
from transaction_risk_individual where final_risk_score is not null
and final_risk_score='High Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Individual' as risk_type,  0 as High_Risk_Count, 0 as Medium_Risk_Count,count(final_risk_score) as Low_Risc_Count
from transaction_risk_individual where final_risk_score is not null
and final_risk_score='Low Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Individual' as risk_type,  0 as High_Risk_Count, count(final_risk_score) as Medium_Risc_Count, 0 as Low_Risk_Count
from transaction_risk_individual where final_risk_score is not null
and final_risk_score='Medium Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Corporate' as risk_type,  count(final_risk_score) as High_Risk_Count,0 as Medium_Risk_Count,0 as Low_Risk_Count
from transaction_risk_Corporate where final_risk_score is not null
and final_risk_score='High Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Corporate' as risk_type,  0 as High_Risk_Count, 0 as Medium_Risk_Count,count(final_risk_score) as Low_Risc_Count
from transaction_risk_Corporate where final_risk_score is not null
and final_risk_score='Low Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Corporate' as risk_type,  0 as High_Risk_Count, count(final_risk_score) as Medium_Risc_Count, 0 as Low_Risk_Count
from transaction_risk_Corporate where final_risk_score is not null
and final_risk_score='Medium Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Correspondent' as risk_type,  count(final_risk_score) as High_Risk_Count,0 as Medium_Risk_Count,0 as Low_Risk_Count
from transaction_risk_Bank where final_risk_score is not null
and final_risk_score='High Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Correspondent' as risk_type,  0 as High_Risk_Count, 0 as Medium_Risk_Count,count(final_risk_score) as Low_Risc_Count
from transaction_risk_Bank where final_risk_score is not null
and final_risk_score='Low Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Correspondent' as risk_type,  0 as High_Risk_Count, count(final_risk_score) as Medium_Risc_Count, 0 as Low_Risk_Count
from transaction_risk_Bank where final_risk_score is not null
and final_risk_score='Medium Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Vendor' as risk_type,  count(final_risk_score) as High_Risk_Count,0 as Medium_Risk_Count,0 as Low_Risk_Count
from transaction_risk_Vendor where final_risk_score is not null
and final_risk_score='High Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Vendor' as risk_type,  0 as High_Risk_Count, 0 as Medium_Risk_Count,count(final_risk_score) as Low_Risc_Count
from transaction_risk_Vendor where final_risk_score is not null
and final_risk_score='Low Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
UNION
SELECT 'Vendor' as risk_type,  0 as High_Risk_Count, count(final_risk_score) as Medium_Risc_Count, 0 as Low_Risk_Count
from transaction_risk_Vendor where final_risk_score is not null
and final_risk_score='Medium Risk' AND dateofassessment<= To_Date and Client_Id = c_clientId
group by risk_type,  final_risk_score
) as Tbl_summary group by risk_type
;
END ;;
DELIMITER ;
