CREATE  PROCEDURE `get_risk_score_customerwise_all`(
	IN `c_from_date` DATE, `c_to_date` DATE, C_Cust_Type VARCHAR(25)
    )
BEGIN
DECLARE From_date, To_Date DATETIME;
SET From_Date = DATE_ADD(c_from_date, INTERVAL 0 DAY);
SET To_Date = DATE_ADD(c_to_date, INTERVAL 1 DAY);
CASE C_Cust_Type
WHEN  'Individual' THEN
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername,'Individual' as risk_type,  COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_individual
	where id in(select max(id) as latest_score FROM transaction_risk_individual where dateofassessment BETWEEN From_Date AND To_Date group by customercode)
	;
WHEN  'Corporate' THEN
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername,'Corporate' as risk_type, COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_corporate
	where id in(select max(id) as latest_score FROM transaction_risk_corporate where dateofassessment BETWEEN From_Date AND To_Date group by customercode);
WHEN  'Bank' THEN
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername, 'Bank' as risk_type, COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_bank
	where id in(select max(id) as latest_score FROM transaction_risk_bank where dateofassessment BETWEEN From_Date AND To_Date group by customercode);
WHEN  'Vendor' THEN
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername,'Vendor' as risk_type,  COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_vendor
	where id in(select max(id) as latest_score FROM transaction_risk_vendor where dateofassessment BETWEEN From_Date AND To_Date  group by customercode)
	;
ELSE
	SELECT * from
	(
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername,'Individual' as risk_type,  COALESCE(final_risk_score,'') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_individual
	where id in(select max(id) as latest_score FROM transaction_risk_individual where dateofassessment BETWEEN From_Date AND To_Date group by customercode)
	UNION
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername,'Corporate' as risk_type, COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_corporate
	where id in(select max(id) as latest_score FROM transaction_risk_corporate where dateofassessment BETWEEN From_Date AND To_Date group by customercode)
	UNION
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername, 'Bank' as risk_type, COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_bank
	where id in(select max(id) as latest_score FROM transaction_risk_bank where dateofassessment BETWEEN From_Date AND To_Date group by customercode)
	UNION
	select id as s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') as entry_date , customercode, customername,'Vendor' as risk_type,  COALESCE(final_risk_score,' ') as final_score, COALESCE(risk_score_before_override,' ') as score_before_override
	from transaction_risk_vendor
	where id in(select max(id) as latest_score FROM transaction_risk_vendor where dateofassessment BETWEEN From_Date AND To_Date  group by customercode)
	) QRY_ALL_CUSTOMER ORDER BY s_no;
END CASE
;
END ;;
DELIMITER ;
