    ,CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname, '')) AS 'created_by',a.remarks AS remarks
    FROM transaction_risk_individual_v2 a
    LEFT JOIN USER u ON a.created_by = u.id
	WHERE  a.Client_Id = c_clientId AND IsDeleted=0   AND  a.id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_individual_v2 WHERE dateofassessment BETWEEN From_Date AND To_Date  GROUP BY customercode)
	AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
	WHEN 2 THEN a.final_risk_score = 'Medium Risk'
	WHEN 3 THEN a.final_risk_score = 'High Risk'
	ELSE 1=1
	END)
	UNION
	SELECT a.id AS s_no, DATE_FORMAT(a.dateofassessment,'%d/%m/%Y') AS entry_date , a.customercode, IFNULL(customername,' ')customername,'Corporate' AS risk_type, COALESCE(a.final_risk_score,' ') AS final_score, COALESCE(a.risk_score_before_override,' ') AS score_before_override,a.assessment_version
   ,CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname, '')) AS 'created_by',a.remarks as remarks
    FROM transaction_risk_corporate_v2 a
        LEFT JOIN USER u ON a.created_by = u.id
	WHERE a.Client_Id = c_clientId AND IsDeleted=0   AND  a.id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_corporate_v2 WHERE dateofassessment BETWEEN From_Date AND To_Date  GROUP BY customercode)
	AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
