CREATE  PROCEDURE `get_risk_score_customerwise_all_with_dupli`(
	IN `c_from_date` DATE,
    `c_to_date` DATE,
    C_Cust_Type VARCHAR(25),
    IN `c_clientId` INT,
    c_risk_level INT,
    IN p_created_by INT
    )
BEGIN
DECLARE From_date, To_Date DATETIME;
SET From_Date = DATE_ADD(c_from_date, INTERVAL 0 DAY);
SET To_Date = DATE_ADD(c_to_date, INTERVAL 1 DAY);
CASE C_Cust_Type
WHEN  'Individual' THEN
	SELECT a.id AS s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') AS entry_date , customercode, IFNULL(customername,'')customername,'Individual' AS risk_type,  COALESCE(final_risk_score,' ') AS final_score, COALESCE(risk_score_before_override,' ') AS score_before_override,a.assessment_version
	,CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname, '')) AS 'created_by',a.remarks as remarks
    FROM transaction_risk_individual a
    LEFT JOIN USER u ON a.created_by = u.id
	WHERE  dateofassessment BETWEEN From_Date AND To_Date AND
	a.Client_Id = c_clientId AND IsDeleted=0
	AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
	WHEN 2 THEN a.final_risk_score = 'Medium Risk'
	WHEN 3 THEN a.final_risk_score = 'High Risk'
	ELSE 1=1
	END)
    ORDER BY  s_no ;
WHEN  'Corporate' THEN
	SELECT a.id AS s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') AS entry_date , customercode, IFNULL(customername,'')customername,'Corporate' AS risk_type, COALESCE(final_risk_score,' ') AS final_score, COALESCE(risk_score_before_override,' ') AS score_before_override,a.assessment_version
	,CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname, '')) AS 'created_by',a.remarks AS remarks
    FROM transaction_risk_corporate a
    LEFT JOIN USER u ON a.created_by = u.id
	WHERE  dateofassessment BETWEEN From_Date AND To_Date AND
    a.Client_Id = c_clientId AND IsDeleted=0 AND a.created_by
	LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
	WHEN 2 THEN a.final_risk_score = 'Medium Risk'
	WHEN 3 THEN a.final_risk_score = 'High Risk'
	ELSE 1=1
	END)
    ORDER BY s_no;
WHEN  'Bank' THEN
	SELECT a.id AS s_no, DATE_FORMAT(dateofassessment,'%d/%m/%Y') AS entry_date , customercode, IFNULL(customername,'')customername, 'Bank' AS risk_type, COALESCE(final_risk_score,' ') AS final_score, COALESCE(risk_score_before_override,' ') AS score_before_override,a.assessment_version
	,CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname, '')) AS 'created_by',a.remarks AS remarks
