/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_risk_verbose`(
IN `c_from_date` DATE,
    `c_to_date` DATE,
IN c_risk_level INT,
    IN clientId INT,
    IN C_Cust_Type VARCHAR(25),
     IN p_created_by INT
)
BEGIN
DECLARE From_date, To_Date DATETIME;
SET From_Date = DATE_ADD(c_from_date, INTERVAL 0 DAY);
SET To_Date = DATE_ADD(c_to_date, INTERVAL 1 DAY);
CASE C_Cust_Type
WHEN  'Individual' THEN
SELECT
a.customercode,
a.customername,
IF(cm.cust_type = 'I', 'INDIVIDUAL', 'CORPORATE') AS risk_type,
a.dateofassessment,
a.assessment_version,
a.risk_score_sum,
a.risk_score_count,
a.risk_score_before_override,
a.final_risk_score,
a.Customer_nationality,
LTM.lov_type_name AS lov_type_name,
IF(LTM.lov_country_duplicate = 1, CT.name, LM.lov_risk_data) AS lov_risk_data,
IF(LTM.lov_country_duplicate = 1, CT.RiskRating, LM.lov_risk_score) AS lov_risk_score,
IF(LTM.lov_country_duplicate = 1, CT.FATFRISKRating, LM.Over_ride_Score) AS Over_ride_Score
    FROM transaction_risk_individual a
    LEFT JOIN USER u ON a.created_by = u.id INNER JOIN customermaster cm ON a.customercode = cm.cust_ref_id
INNER JOIN  transaction_risk_category_type_score TSCORE ON a.customercode = TSCORE.customer_code
AND a.assessment_version = TSCORE.assessment_version
INNER JOIN
lovtypemaster_backup LTM ON TSCORE.trans_risk_type_id = LTM.lov_type_id
LEFT JOIN
lovmaster LM ON LM.id = TSCORE.trans_risk_item_id
LEFT JOIN
country CT ON CT.id = TSCORE.trans_risk_item_id
WHERE  a.Client_Id = clientId AND IsDeleted=0   AND  a.id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_individual WHERE dateofassessment BETWEEN From_Date AND To_Date  GROUP BY customercode)
AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
WHEN 2 THEN a.final_risk_score = 'Medium Risk'
WHEN 3 THEN a.final_risk_score = 'High Risk'
ELSE 1=1
END);
WHEN  'Corporate' THEN
SELECT
a.customercode,
a.customername,
IF(cm.cust_type = 'I', 'INDIVIDUAL', 'CORPORATE') AS risk_type,
a.dateofassessment,
a.assessment_version,
a.risk_sum,
a.risk_count,
a.risk_score_before_override,
a.final_risk_score,
a.Customer_nationality,
LTM.lov_type_name AS lov_type_name,
IF(LTM.lov_country_duplicate = 1, CT.name, LM.lov_risk_data) AS lov_risk_data,
IF(LTM.lov_country_duplicate = 1, CT.RiskRating, LM.lov_risk_score) AS lov_risk_score,
IF(LTM.lov_country_duplicate = 1, CT.FATFRISKRating, LM.Over_ride_Score) AS Over_ride_Score
    FROM transaction_risk_corporate a
        LEFT JOIN USER u ON a.created_by = u.id INNER JOIN
        customermaster cm ON a.customercode = cm.cust_ref_id
INNER JOIN  transaction_risk_category_type_score TSCORE ON a.customercode = TSCORE.customer_code
AND a.assessment_version = TSCORE.assessment_version
INNER JOIN
lovtypemaster_backup LTM ON TSCORE.trans_risk_type_id = LTM.lov_type_id
LEFT JOIN
lovmaster LM ON LM.id = TSCORE.trans_risk_item_id
LEFT JOIN
country CT ON CT.id = TSCORE.trans_risk_item_id
WHERE a.Client_Id = clientId AND IsDeleted=0   AND  a.id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_corporate WHERE dateofassessment BETWEEN From_Date AND To_Date  GROUP BY customercode)
AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
WHEN 2 THEN a.final_risk_score = 'Medium Risk'
WHEN 3 THEN a.final_risk_score = 'High Risk'
ELSE 1=1
END);
ELSE
SELECT * FROM
(SELECT
a.customercode,
a.customername,
IF(cm.cust_type = 'I', 'INDIVIDUAL', 'CORPORATE') AS risk_type,
a.dateofassessment,
a.assessment_version,
a.risk_score_sum,
a.risk_score_count,
a.risk_score_before_override,
a.final_risk_score,
a.Customer_nationality,
LTM.lov_type_name AS lov_type_name,
IF(LTM.lov_country_duplicate = 1, CT.name, LM.lov_risk_data) AS lov_risk_data,
IF(LTM.lov_country_duplicate = 1, CT.RiskRating, LM.lov_risk_score) AS lov_risk_score,
IF(LTM.lov_country_duplicate = 1, CT.FATFRISKRating, LM.Over_ride_Score) AS Over_ride_Score
    FROM transaction_risk_individual a
    LEFT JOIN USER u ON a.created_by = u.id INNER JOIN customermaster cm ON a.customercode = cm.cust_ref_id
INNER JOIN  transaction_risk_category_type_score TSCORE ON a.customercode = TSCORE.customer_code
AND a.assessment_version = TSCORE.assessment_version
INNER JOIN
lovtypemaster_backup LTM ON TSCORE.trans_risk_type_id = LTM.lov_type_id
LEFT JOIN
lovmaster LM ON LM.id = TSCORE.trans_risk_item_id
LEFT JOIN
country CT ON CT.id = TSCORE.trans_risk_item_id
WHERE  a.Client_Id = clientId AND IsDeleted=0   AND  a.id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_individual WHERE dateofassessment BETWEEN From_Date AND To_Date  GROUP BY customercode)
AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
WHEN 2 THEN a.final_risk_score = 'Medium Risk'
WHEN 3 THEN a.final_risk_score = 'High Risk'
ELSE 1=1
END)
UNION
SELECT
a.customercode,
a.customername,
IF(cm.cust_type = 'I', 'INDIVIDUAL', 'CORPORATE') AS risk_type,
a.dateofassessment,
a.assessment_version,
a.risk_sum,
a.risk_count,
a.risk_score_before_override,
a.final_risk_score,
a.Customer_nationality,
LTM.lov_type_name AS lov_type_name,
IF(LTM.lov_country_duplicate = 1, CT.name, LM.lov_risk_data) AS lov_risk_data,
IF(LTM.lov_country_duplicate = 1, CT.RiskRating, LM.lov_risk_score) AS lov_risk_score,
IF(LTM.lov_country_duplicate = 1, CT.FATFRISKRating, LM.Over_ride_Score) AS Over_ride_Score
    FROM transaction_risk_corporate a
        LEFT JOIN USER u ON a.created_by = u.id INNER JOIN
        customermaster cm ON a.customercode = cm.cust_ref_id
INNER JOIN  transaction_risk_category_type_score TSCORE ON a.customercode = TSCORE.customer_code
AND a.assessment_version = TSCORE.assessment_version
INNER JOIN
lovtypemaster_backup LTM ON TSCORE.trans_risk_type_id = LTM.lov_type_id
LEFT JOIN
lovmaster LM ON LM.id = TSCORE.trans_risk_item_id
LEFT JOIN
country CT ON CT.id = TSCORE.trans_risk_item_id
WHERE a.Client_Id = clientId AND IsDeleted=0   AND  a.id IN(SELECT MAX(id) AS latest_score FROM transaction_risk_corporate WHERE dateofassessment BETWEEN From_Date AND To_Date  GROUP BY customercode)
AND a.created_by LIKE IF(p_created_by IS NULL OR p_created_by = 0, '%', p_created_by)
    AND (CASE c_risk_level WHEN 1 THEN a.final_risk_score = 'Low Risk'
WHEN 2 THEN a.final_risk_score = 'Medium Risk'
WHEN 3 THEN a.final_risk_score = 'High Risk'
ELSE 1=1
END)) QRY_ALL_CUSTOMER ;
END CASE;
END ;;
DELIMITER ;
