DELIMITER ;;
CREATE  PROCEDURE `get_sanction_screening_logs`(
In p_name Varchar(200),
In p_nationality Varchar(200),
In p_clientId int,
In p_dob varchar(200),
In p_custType varchar(300))
BEGIN
SELECT
	cust_name,
	nationality,
	dateofbirth,
    search_type,
	match_name,
	match_score,
	match_uid,
	match_category,
	match_type,
	match_nationality,
	match_idnum,
	match_dob,
	created_by,
    cust_type,
	 created_on,
    (SELECT CONCAT(IFNULL(`fname`, ''), ' ', IFNULL(`lname`, '')) FROM `user` `u` WHERE `u`.`id` = `cc`.`created_by`) AS `created_user`
	FROM sanction_screening_log  cc
	where   (cc.cust_name = p_name OR p_name IS NULL)
AND (cc.nationality = p_nationality OR p_nationality IS NULL)
AND (cc.Client_Id = p_clientId OR p_clientId IS NULL)
AND (cc.cust_type = p_custType OR p_custType IS NULL)
	ORDER BY cc.created_on DESC;
END ;;
DELIMITER ;
