CREATE  PROCEDURE `get_sanction_screening_log_by_date`(
	in `p_datef` DATE,
    in `p_datet` DATE	,
    in `p_clientId` Int
)
BEGIN
	DECLARE p_datefrom DATETIME;
    DECLARE p_dateto DATETIME;
    SET p_datefrom = p_datef;
	SET p_dateto = DATE_ADD(p_datet, INTERVAL 1 DAY);
	SELECT
	cust_name,
	nationality,
	dateofbirth,
    search_type,
	match_name,
	match_score,
	match_uid,
	match_category,
	match_type,
	match_nationality,
	match_idnum,
	match_dob,
	created_by,
	 created_on
	FROM sanction_screening_log  cc
	WHERE  cc.created_on
    BETWEEN p_datefrom AND p_dateto and cc.Client_Id = p_clientId
	ORDER BY cc.created_on DESC;
END ;;
DELIMITER ;
