CREATE  PROCEDURE `get_sanction_screening_pgnd`(
	IN p_startDate DATETIME,
    IN p_endDate DATETIME
)
BEGIN
	SELECT `id`,
		`cust_name`,
		`nationality`,
		`dateofbirth`,
		`search_type`,
		`match_name`,
		`match_score`,
		`match_uid`,
		`match_category`,
		`match_type`,
		`match_nationality`,
		`match_idnum`,
		`match_dob`,
		`created_by`,
		`created_on`
    FROM `sanction_screening_log` WHERE `created_on` >= p_startDate AND `created_on` <= p_endDate
    ORDER BY created_on DESC;
END ;;
