CREATE  PROCEDURE `get_transactioncase_by_id`(IN p_id INT)
BEGIN
SELECT
	 `transactionscreen`.`id`,
    `transactionscreen`.`tranrefno`,
    `transactionscreen`.`custrefno`,
    `transactionscreen`.`custtype`,
    `transactionscreen`.`name`,
    `transactionscreen`.`country`,
    `transactionscreen`.`dob`,
    `transactionscreen`.`threshold`,
    `transactionscreen`.`ismatched`,
    `transactionscreen`.`matchname`,
    `transactionscreen`.`matchscore`,
    `transactionscreen`.`source`,
    `transactionscreen`.`source_unique_id`,
    `transactionscreen`.`match_type`,
    `transactionscreen`.`match_category`,
    `transactionscreen`.`iswhitelisted`,
    `transactionscreen`.`comments`,
    `transactionscreen`.`assignedto`,
    `transactionscreen`.`status`,
    `transactionscreen`.`createdby`,
    `transactionscreen`.`createdon`,
    `transactionscreen`.`updatedby`,
    `transactionscreen`.`updatedon`,
   CONCAT(IFNULL(u.fname, ''), ' ', IFNULL(u.lname,'')) AS `updated_user`,
	us.user_name AS `created_user`
FROM  transactionscreen
    LEFT JOIN USER u ON transactionscreen.updatedby = u.id
    LEFT JOIN USER us ON transactionscreen.createdby = us.id
WHERE transactionscreen.id=p_id;
END ;;
DELIMITER ;
