DELIMITER ;;
CREATE  PROCEDURE `get_tran_risk_bank_by_id`(
	IN p_id INT
)
BEGIN
	SELECT TRC.*,
   	LTM.lov_type_category_id,
	TSCORE.trans_risk_type_id AS lov_type_id,
	LTM.lov_country_duplicate,
	IF(LTM.lov_country_duplicate = 1, CT.name, LM.lov_risk_data) AS lov_risk_data,
	IF(LTM.lov_country_duplicate = 1, CT.RiskRating, LM.lov_risk_score) AS lov_risk_score,
	IF(LTM.lov_country_duplicate = 1, CT.FATFRISKRating, LM.Over_ride_Score) AS Over_ride_Score
	FROM TRANSACTION_RISK_BANK TRC
	INNER JOIN transaction_risk_category_type_score TSCORE ON TRC.customercode = TSCORE.customer_code AND TRC.assessment_version=TSCORE.assessment_version
	INNER JOIN lovtypemaster_backup LTM ON LM.lov_type_id = LTM.lov_type_id
   LEFT JOIN lovmaster LM
            ON LM.id = TSCORE.trans_risk_item_id
	LEFT JOIN country CT
            ON CT.id = TSCORE.trans_risk_item_id
	WHERE TRC.id = p_id;
END ;;
DELIMITER ;
