/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_usergroupaccessright`(
IN p_user_group_id INT,
IN p_user_id INT,
IN p_func_code VARCHAR(100),
IN p_module_code VARCHAR(100)
)
BEGIN
IF EXISTS(SELECT `id` FROM `module` WHERE `code`=p_module_code)
THEN
	IF EXISTS(SELECT f.`id` FROM `functionality` f INNER JOIN module m ON f.module_id=m.id WHERE f.`code`=p_func_code AND m.`code`=p_module_code)
	THEN
		IF EXISTS(SELECT `id` FROM `module` WHERE `code`=p_module_code AND `allowanonymous`=1)
		THEN
			SELECT 1;
		ELSE
			IF EXISTS(SELECT f.`id` FROM `functionality` f INNER JOIN module m ON f.module_id=m.id WHERE f.`code`=p_func_code AND m.`code`=p_module_code AND f.`allowanonymous`=1)
			THEN
				SELECT 1;
			ELSE
				SELECT COUNT(ugr.user_group_id) FROM usergroupright ugr
				INNER JOIN module m ON ugr.module_id=m.id
				INNER JOIN functionality f ON ugr.func_id=f.id and f.module_id = m.id
                inner join user u on u.id = p_user_id
                inner join client_right_master crm on crm.Menu_Id = f.Menu_Id and crm.client_id = u.client_id
				WHERE ugr.user_group_id=p_user_group_id
				AND m.`code`=p_module_code
				AND f.`code`=p_func_code;
			END IF;
		END IF;
	ELSE
		SELECT 1;
	END IF;
ELSE
	SELECT 1;
END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_usergroupright_by_module_id` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `get_usergroupright_by_module_id`(IN p_module_id INT)
BEGIN
SELECT
	`ugr`.`user_group_id` AS `user_group_id`,
    `ug`.`code` AS `user_group_code`,
    `ug`.`name` AS `user_group_name`,
    `ugr`.`module_id` AS `module_id`,
    `md`.`code` AS `module_code`,
    `md`.`name` AS `module_name`,
    `ugr`.`func_id` AS `func_id`,
    `fnc`.`code` AS `func_code`,
    `fnc`.`name` AS `func_name`
FROM
	`usergroupright` `ugr`
INNER JOIN `module` `md`
	ON `md`.`id`=`ugr`.`module_id`
INNER JOIN `functionality` `fnc`
	ON `fnc`.`id`=`ugr`.`func_id`
INNER JOIN `usergroup` `ug`
	ON `ug`.`id`=`ugr`.`user_group_id`
WHERE
	`ugr`.`module_id`=p_module_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_usergroupright_by_user_group_id` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
