CREATE  PROCEDURE `get_usergroupright_by_user_group_id`(IN p_user_group_id INT)
BEGIN
SELECT
	`ugr`.`user_group_id` AS `user_group_id`,
    `ug`.`code` AS `user_group_code`,
    `ug`.`name` AS `user_group_name`,
    `ugr`.`module_id` AS `module_id`,
    `md`.`code` AS `module_code`,
    `md`.`name` AS `module_name`,
    m.menu_id as module_code,
    m.menu_name as module_name,
    `md`.`allowanonymous` AS `allow_anonymous`,
    `ugr`.`func_id` AS `func_id`,
    `fnc`.`code` AS `func_code`,
    `fnc`.`name` AS `func_name`
FROM
	`usergroupright` `ugr`
INNER JOIN `module` `md`
	ON `md`.`id`=`ugr`.`module_id`
INNER JOIN `functionality` `fnc`
	ON `fnc`.`id`=`ugr`.`func_id`
INNER JOIN `usergroup` `ug`
	ON `ug`.`id`=`ugr`.`user_group_id`
inner join menu_master m on m.menu_id = fnc.menu_id
WHERE
	`ugr`.`user_group_id`=p_user_group_id ;
END ;;
DELIMITER ;
