CREATE  PROCEDURE `get_user_password_expiry`(In p_user_id int)
BEGIN
SELECT UserId
FROM user_password_history
WHERE UserId = p_user_id
GROUP BY UserId
HAVING DATE(MAX(UpdatedOn)) < CURDATE();
END ;;
