CREATE  PROCEDURE `ins_client`(
    IN p_Client_Name VARCHAR(255),
    IN p_Prefix VARCHAR(50),
    IN p_C6Username VARCHAR(100),
    IN p_C6Threshold INT,
    IN p_Threshold INT,
    IN p_createdBy INT,
    IN p_description TEXT,
    IN p_complem VARCHAR(255),
    IN p_C6BaseUrl VARCHAR(255),
    IN p_ApplicationStartDate DATETIME,
    IN p_ApplicationEndDate DATETIME,
    IN p_SearchCount INT
)
BEGIN
    INSERT INTO client_master (
        Client_Name,
        Prefix,
        C6Username,
        C6Threshold,
        Threshold,
        Created_By,
        Created_On,
        Description,
        catogory_value,
        C6BaseUrl,
        ApplicationStartDate,
        ApplicationEndDate,
        searchcount,
        is_active
    ) VALUES (
        p_Client_Name,
        p_Prefix,
        p_C6Username,
        p_C6Threshold,
        p_Threshold,
        p_createdBy,
        NOW(),
        p_description,
        p_complem,
        p_C6BaseUrl,
        p_ApplicationStartDate,
        p_ApplicationEndDate,
        p_SearchCount,
        1
    );
    SELECT LAST_INSERT_ID();
END ;;
