CREATE  PROCEDURE `ins_codes`(
 IN `CodType` VARCHAR(30),
    IN `CodCode` VARCHAR(30),
    IN `CodName` VARCHAR(30),
    IN `CodDetails` VARCHAR(30),
    In `CodFlexi1`  VARCHAR(30),
    IN `CodFlexi2`  VARCHAR(30),
    IN `CodClientId` INT )
BEGIN
	DECLARE `@value` VARCHAR(30);
	SELECT `COD_NAME` INTO `@value` FROM `codes_table` WHERE  `COD_TYPE` = `CodType` AND `COD_NAME` = `CodName` AND `COD_CLIENT_ID` = `CodClientId`;
	IF(`@value` is null)
	THEN
		INSERT INTO `codes_table` (`COD_TYPE`, `COD_CODE`,`COD_NAME` ,`COD_DETAILS`,`COD_CLIENT_ID`,`COD_ACTIVE_YN` ,`COD_FLEXI1`,`COD_FLEXI2`,`COD_FLEXI3`,`COD_CODE_CATEG`) VALUES (`CodType`, `CodCode`, `CodName`, `CodDetails`,`CodClientId`,1,`CodFlexi1`,`CodFlexi2`,NULL,NULL);
		SELECT 1;
	END IF;
END ;;
DELIMITER ;
