CREATE  PROCEDURE `ins_corporate_shareholder_new`(
	IN c_corporate_id INT,
    IN c_share_holder_id INT,
    IN c_share_percentage INT,
    IN c_cust_ref_id VARCHAR(250),
    IN c_status INT,
    IN c_created_by INT
)
BEGIN
	INSERT INTO `corporateshareholder`
				(`corporate_id`, `share_holder_id`, `share_percentage`, `cust_ref_id`, `status`, `created_by`)
		VALUES 	(c_corporate_id, c_share_holder_id, c_share_percentage, c_cust_ref_id, c_status, c_created_by);
	UPDATE  `corporateshareholder`
		SET  `cust_id_gen`= CONCAT(`cust_ref_id`,`id`)
		WHERE `id`=last_insert_id();

	SELECT `cust_id_gen` FROM  `corporateshareholder`
				WHERE `id`=last_insert_id();
END ;;
