CREATE  PROCEDURE `ins_customercase_prefix`(
 IN `p_cust_id` VARCHAR(250),
 IN `p_created_by` INT,
 IN `p_cust_master_id` INT,
 IN `p_match_category` VARCHAR(250),
 IN `p_match_type` VARCHAR(250),
 IN `p_clientId` INT,
 IN p_c6threshold INT,
 IN p_threshold INT,
 in p_birthyear varchar(20),
 in p_gender varchar(10),
  IN p_createdon datetime,
IN p_match_score INT,
IN p_source VARCHAR(250),
IN p_source_unique_id VARCHAR(250),
In p_caseChangeStatus VARCHAR(500),
  IN p_is_matched INT,
  In p_status INT
 )
BEGIN
DECLARE Createddate datetime;
if(p_clientId is null or p_clientId = 0)
then
set p_clientId = (select client_Id from customermaster where id  = p_cust_master_id);
end if;
if(p_createdon is null or p_createdon = '0001-01-01 00:00:00')
then
set Createddate = now();
else
set Createddate=p_createdon;
end if;
if(p_created_by is null or p_created_by = 0)
then
set p_created_by = (select created_by from customermaster where id  = p_cust_master_id);
end if;


begin
INSERT INTO `customercase`
(
cust_master_id,
cust_id,
created_by,
is_deleted,
`status`,
`match_category`,
`match_type`,
created_on,
    Client_Id,
    c6threshold,
    threshold,
    `assigned_to`,
    birthyear,
    gender,
    `is_matched`,
    `match_score`,
    `source`,
    `source_unique_id`,
    `case_change_status`
  )
 VALUES (
p_cust_master_id,
p_cust_id,
    p_created_by,
0,
p_status,
p_match_category,
p_match_type,
Createddate,
    p_clientId,
    p_c6threshold,
    p_threshold,
    1,
    p_birthyear,
    p_gender,
    p_is_matched,
    p_match_score,
    p_source,
    p_source_unique_id,
    p_caseChangeStatus
 );
SELECT last_insert_id();
END;

end ;;
DELIMITER ;
