CREATE  PROCEDURE `ins_customermaster_and_shareholder`(
IN p_cust_ref_id VARCHAR(45),
IN p_fname VARCHAR(100),
IN p_mname VARCHAR(100),
IN p_lname VARCHAR(100),
IN p_dob DATETIME,
IN p_nationality VARCHAR(200),
IN p_cust_type ENUM('I','C','S','B','V'),
IN p_cust_id_type VARCHAR(25),
IN p_cust_id_number VARCHAR(50),
IN p_mobile VARCHAR(15),
IN p_created_by INT(11),

IN c_corporate_id INT,
IN c_share_percentage INT
   )
BEGIN

DECLARE var_customerid_of_shareholder, var_shareholder_id INT DEFAULT 0;
DECLARE var_cust_refid_gen VARCHAR(45) DEFAULT NULL;

INSERT INTO `corporateshareholder`
				(`corporate_id`,  `share_percentage`, `cust_ref_id`,  `created_by`)
		VALUES 	(c_corporate_id,  c_share_percentage, p_cust_ref_id,  p_created_by);
SET var_shareholder_id =last_insert_id();
SET  var_cust_refid_gen = CONCAT(p_cust_ref_id,var_shareholder_id);
INSERT INTO customermaster
(
`cust_ref_id`,
`fname`,
`mname`,
`lname`,
`dob`,
`nationality`,
`cust_type`,
`cust_id_type`,
`cust_id_number`,
`mobile`,
`created_by`
  )
VALUES
(
var_cust_refid_gen ,
p_fname ,
p_mname ,
p_lname ,
p_dob ,
p_nationality ,
p_cust_type ,
p_cust_id_type ,
p_cust_id_number ,
p_mobile ,
p_created_by
  );
SET var_customerid_of_shareholder = LAST_INSERT_ID();


INSERT INTO `customercase` (
	`cust_master_id`,
    `cust_id`,
    `status`,
    `is_deleted`,
    `match_category`,
    `created_by`,
    `created_on`
) VALUE(
	var_customerid_of_shareholder,
    p_cust_ref_id,
    0,
    0,
    'INDIVIDUAL',
    p_created_by,
    NOW()
);

	UPDATE  `corporateshareholder`
		SET
        `share_holder_id`=var_customerid_of_shareholder,
        `cust_id_gen`= var_cust_refid_gen
		WHERE `id`=var_shareholder_id;

               SELECT var_customerid_of_shareholder;
END ;;
DELIMITER ;
