CREATE  PROCEDURE `ins_customermaster_and_shareholder_prefix`(
IN p_cust_ref_id VARCHAR(45),
IN p_fname VARCHAR(100),
IN p_mname VARCHAR(100),
IN p_lname VARCHAR(100),
IN p_dob DATETIME,
IN p_nationality VARCHAR(200),
IN p_cust_type ENUM('I','C','S','B','V'),
IN p_cust_id_type VARCHAR(25),
IN p_cust_id_number VARCHAR(50),
IN p_mobile VARCHAR(15),
IN p_created_by INT(11),
IN p_customer_type VARCHAR(45),

IN c_corporate_id VARCHAR(25),
IN c_share_percentage INT,
IN c_clientId INT,
IN p_c6threshold INT(11),
IN threshold INT(11),
IN p_designation VARCHAR(45),
IN p_emirates_id VARCHAR(45),
IN p_emirates_id_expiry VARCHAR(45),
IN p_passport_expiry VARCHAR(45)
   )
BEGIN

DECLARE var_customerid_of_shareholder, var_shareholder_id VARCHAR(25) DEFAULT 0;
DECLARE var_cust_refid_gen VARCHAR(45) DEFAULT NULL;
DECLARE assigned_to INT DEFAULT 0;

INSERT INTO `corporateshareholder`
				(`corporate_id`,  `share_percentage`, `cust_ref_id`,  `created_by`)
		VALUES 	(c_corporate_id,  c_share_percentage, p_cust_ref_id,  p_created_by);
SET var_shareholder_id =LAST_INSERT_ID();
SET  var_cust_refid_gen = CONCAT(p_cust_ref_id,var_shareholder_id);
INSERT INTO customermaster
(
`cust_ref_id`,
`fname`,
`mname`,
`lname`,
`dob`,
`nationality`,
`cust_type`,
`cust_id_type`,
`cust_id_number`,
`mobile`,
`created_by`,
`Client_Id`,
`customer_type`,
`designation`,
`emirates_id`,
`emirates_id_expiry`,
`passport_expiry`
  )
VALUES
(
var_cust_refid_gen ,
p_fname ,
p_mname ,
p_lname ,
p_dob ,
p_nationality ,
p_cust_type ,
p_cust_id_type ,
p_cust_id_number ,
p_mobile ,
p_created_by ,
c_clientId,
p_customer_type,
p_designation,
p_emirates_id,
p_emirates_id_expiry,
p_passport_expiry
  );
SET var_customerid_of_shareholder = LAST_INSERT_ID();


SET assigned_to = (SELECT id FROM USER WHERE client_id = c_clientId AND user_group_id = 1 AND is_active = 1 LIMIT 1);
INSERT INTO `customercase` (
	`cust_master_id`,
    `cust_id`,
    `status`,
    `is_deleted`,
    `match_category`,
    `created_by`,
    `created_on`,
    `Client_Id`,
    c6threshold,
    threshold,assigned_to
) VALUE(
	var_customerid_of_shareholder,
    var_cust_refid_gen,
    0,
    0,
    'INDIVIDUAL',
    p_created_by,
    NOW(),
    c_clientId,
    p_c6threshold,
    threshold,assigned_to
);


	UPDATE  `corporateshareholder`
		SET
        `share_holder_id`=var_customerid_of_shareholder,
        `cust_id_gen`= var_cust_refid_gen
		WHERE `id`=var_shareholder_id;

                SELECT cust_id FROM `customercase`  WHERE `cust_id`=var_cust_refid_gen;
END ;;
DELIMITER ;
