CREATE  PROCEDURE `ins_customer_master`(
IN `p_fname` VARCHAR(250),
 IN `p_mname` VARCHAR(250),
 IN `p_lname` VARCHAR(1000),
 IN `p_cust_id` VARCHAR(250),
 IN `p_dob` DATE,
 IN `p_nationality`  VARCHAR(250),
 IN `p_created_by` INT,
 IN `p_batch_id` INT,
 IN `p_mobile` VARCHAR(250),
 IN `p_customer_id_type` VARCHAR(250),
 IN `p_customer_id_number` VARCHAR(250),
 IN p_customer_type VARCHAR(1),
 IN p_prefix VARCHAR(5),
 IN `p_clientId` INT,
 IN p_userName varchar(250),
 IN p_clientName varchar(250),
 In p_companyCode VARCHAR(250),
 IN p_createdon datetime,
 In p_type varchar(200),
In p_deliverychannel varchar(200),
In p_productname varchar(200),
In p_modeofpayment varchar(200),
In p_entitytypetxt varchar(200),
In p_businesstype varchar(200),
In p_residencestatus varchar(200),
In p_profession varchar(200),
In p_cifnumber Varchar(200),
In p_parentid Varchar(100),
In p_screeningoption Varchar(200),
In p_idissuedate date,
In p_idexpirydate date,
In p_residence Varchar(500),
In p_employer Varchar(500),
In p_goldenvisa Varchar(100),
In p_employerindustry Varchar(500),
In p_employersector Varchar(500),
In p_sowsofcountry Varchar(100),
In p_counterparty Varchar(100),
In p_productvalue Varchar(100),
In p_productrefno Varchar(100),
In p_tradelicenseauthority Varchar(100),
In p_tradelicensesector Varchar(100),
In p_desgination Varchar(100),
In p_share int,
In p_counterpartyname varchar(200),
In p_relationship Varchar(100),
In p_flag Varchar(100),
IN p_PassportId VARCHAR(255),
    IN p_PassportIssueDate DATE,
    IN p_PassportExpiryDate DATE,
    IN p_EmiratesIdNumber VARCHAR(255),
    IN p_EmiratesIdIssueDate DATE,
    IN p_EmiratesIdExpiryDate DATE,
    In p_is_duplicate int,
    In p_version int,
     IN p_group_id VARCHAR(100),
     IN p_group_risk VARCHAR(50),
     In p_replaceflag int
)
BEGIN
DECLARE TempId int;
DECLARE NewCustId VARCHAR(250);
DECLARE clientPrefix VARCHAR(25);
DECLARE Createddate datetime;
SET TempId=(Select COALESCE(MAX(id), 0) FROM customermaster);
set TempId = TempId+1 ;
set NewCustId=concat(p_prefix,TempId);
if(p_clientId is null or p_clientId = 0)
then
set p_clientId = (select client_Id from user where user_name  = p_userName);
    set p_clientId = (select client_Id from client_master where client_name = p_clientName);
end if;
if(p_createdon is null or p_createdon = '0001-01-01 00:00:00')
then
set Createddate = now();
else
set Createddate=p_createdon;
end if;
if(p_created_by is null or p_created_by = 0)
then
set p_created_by = (select id from user where user_name  = p_userName and client_id = p_clientId);
end if;
set clientPrefix = (Select Prefix from client_master where Client_ID = p_clientId);
IF (p_cust_id IS NOT NULL AND p_cust_id <> '')
then
set NewCustId=p_cust_id;
else
set NewCustId=concat(clientPrefix,TempId);
end if;

    INSERT INTO `customermaster`
(
`fname`,
`mname`,
`lname`,
`cust_ref_id`,
`dob`,
        `cust_type`,
`nationality`,
`created_by`,
`is_deleted`,
`mobile`,
`cust_id_type`,
`cust_id_number`,
`status`,
`batch_id`,
`created_on`,
        `Client_Id`,
        `company_code`,
        `type`,
        `profession`,
        `mode_of_payment`,
        `delivery_channel`,
        `residence_status`,
        `product_name`,
        `legal_status`,
        `bussiness_type`,
        `cif_number`,
        `parent_id`,
        `screeningoption`,
        `id_issue_date`,
        `id_expiry_date`,
        `residence`,
        `employer`,
        `goldenvisa`,
        `employerindustry`,
        `employersector`,
        `sowsofcountry`,
        `countryparty`,
        `productvalue`,
        `productrefno`,
        `tradelicenseauthority`,
        `tradelicensesector`,
        `share`,
		`designation`,
        `counterypartyname`,
         `relationship`,
        `flagtype`,
        `PassportId`,
        `PassportIssueDate`,
        `PassportExpiryDate`,
        `EmiratesIdNumber`,
        `EmiratesIdIssueDate`,
        `EmiratesIdExpiryDate`,
        `is_duplicate`,
        `version`,
        `group_id`,
        `group_risk`,
        `replaceflag`

)
VALUES (
p_fname,
p_mname,
p_lname,
NewCustId,
p_dob,
        p_customer_type,
p_nationality,
p_created_by,
0,
p_mobile,
p_customer_id_type,
p_customer_id_number,
0,
p_batch_id,
Createddate,
        p_clientId,
        p_companyCode,
        p_type,
        p_profession,
        p_modeofpayment,
        p_deliverychannel,
        p_residencestatus,
        p_productname,
        p_entitytypetxt,
        p_businesstype,
        p_cifnumber,
        p_parentid,
        p_screeningoption,
        p_idissuedate,
        p_idexpirydate,
        p_residence,
        p_employer,
        p_goldenvisa,
        p_employerindustry,
        p_employersector,
        p_sowsofcountry,
        p_counterparty,
        p_productvalue,
        p_productrefno,
        p_tradelicenseauthority,
        p_tradelicensesector,p_share,
        p_desgination,
        p_counterpartyname,
         p_relationship,
        p_flag,
        p_PassportId,
        p_PassportIssueDate,
        p_PassportExpiryDate,
        p_EmiratesIdNumber,
        p_EmiratesIdIssueDate,
        p_EmiratesIdExpiryDate,
        p_is_duplicate,
        p_version,
        p_group_id,
        p_group_risk,
        p_replaceflag
);
SELECT CONCAT(id,'Ø',cust_ref_id)
FROM customermaster
WHERE cust_ref_id = NewCustId
ORDER BY version DESC
LIMIT 1;


END ;;
