CREATE  PROCEDURE `ins_customer_master_backup`(
IN `p_fname` VARCHAR(250),
 IN `p_mname` VARCHAR(250),
 IN `p_lname` VARCHAR(1000),
 IN `p_cust_id` VARCHAR(250),
 IN `p_dob` DATE,
 IN `p_nationality`  VARCHAR(250),
 IN `p_created_by` INT,
 IN `p_batch_id` INT,
 IN `p_mobile` VARCHAR(250),
 IN `p_customer_id_type` VARCHAR(250),
 IN `p_customer_id_number` VARCHAR(250),
 IN p_customer_type VARCHAR(1),
 IN `p_clientId` INT
 )
BEGIN
IF EXISTS  (SELECT id FROM `customermaster`  WHERE `cust_ref_id`=p_cust_id) THEN
BEGIN
    SELECT id FROM `customermaster`  WHERE `cust_ref_id`=p_cust_id;
END;
ELSE
BEGIN
    INSERT INTO `customermaster`
	(
		`fname`,
		`mname`,
		`lname`,
		`cust_ref_id`,
		`dob`,
        `cust_type`,
		`nationality`,
		`created_by`,
		`is_deleted`,
		`mobile`,
		`cust_id_type`,
		`cust_id_number`,
		`status`,
		`batch_id`,
		`created_on`,
        `Client_Id`
	)
	VALUES (
		p_fname,
		p_mname,
		p_lname,
		p_cust_id,
		p_dob,
        p_customer_type,
		p_nationality,
		p_created_by,
		0,
		p_mobile,
		p_customer_id_type,
		p_customer_id_number,
		0,
		p_batch_id,
		NOW(),
        p_clientId
	);
	SELECT last_insert_id();
END;
END IF;
END ;;
