CREATE  PROCEDURE `ins_ewra_config_data`(
IN p_Id INT,
IN p_data VARCHAR(500),
IN p_active_yn INT,
IN p_mode INT,
IN p_typeId INT,
IN p_clientId INT
)
BEGIN
	IF p_mode = 1 THEN
		INSERT INTO ewra_risk_description
		(Type_Id,DESCRIPTION,isActive,CreatedOn,Client_Id)
		VALUES
		(p_typeId,p_data,1,CURRENT_DATE(),p_clientId);
	ELSEIF p_mode = 2 THEN
		INSERT INTO ewra_inherent_risk_description
		(TypeId,InherentRisk,IsActive,CreatedOn,Client_Id)
		VALUES
		(p_typeId,p_data,1,CURRENT_DATE(),p_clientId);
	ELSEIF p_mode = 3 THEN
		INSERT INTO ewra_key_control
		(TypeId,KeyControl,IsActive,CreatedOn,Client_Id)
		VALUES
		(p_typeId,p_data,1,CURRENT_DATE(),p_clientId);
	ELSEIF p_mode = 4 THEN
		INSERT INTO ewra_residual_risk
		(TypeId,ResidualRiskDescription,IsActive,CreatedOn,Client_Id)
		VALUES
		(p_typeId,p_data,1,CURRENT_DATE(),p_clientId);
    END IF;
SELECT LAST_INSERT_ID();
END ;;
DELIMITER ;
