	IN p_risk_score_before_override VARCHAR(15),
	IN p_risk_data VARCHAR(1000),
	IN p_risk_category_count INT,
    IN p_created_by INT,
    in p_version int,
    IN p_remarks varchar(200),
    IN p_riskoverride Varchar(100),
   In p_type varchar(200),
   IN p_product_reference VARCHAR(255), IN p_product_value DECIMAL(18,2), IN p_comments TEXT,In p_caseVersion int
)
BEGIN DECLARE str1 VARCHAR(500);
DECLARE selItemId VARCHAR(45);
DECLARE selTypeId VARCHAR(45);
DECLARE c_index INT DEFAULT 1;
DECLARE c_assessment_version INT;
SET c_assessment_version=(SELECT COUNT(customercode) FROM transaction_risk_corporate WHERE IsDeleted=0 AND customercode=p_customercode)+1;
WHILE c_index <= p_risk_category_count DO
SET
	str1 = (
		SELECT
			SUBSTRING_INDEX(p_risk_data, "¥", 1)
	);
SET
	selTypeId = (
		SELECT
			SUBSTRING_INDEX(str1, 'Ø', 1)
	);
SET
	selItemId = (
		SELECT
			SUBSTRING_INDEX(SUBSTRING_INDEX(str1, 'Ø', 3), 'Ø', -1)
	);
INSERT INTO
	transaction_risk_category_type_score (
		customer_code,
		trans_risk_type_id,
		trans_risk_item_id,
        assessment_version
	)
VALUES
	(p_customercode, selTypeId, selItemId,c_assessment_version);
SET
	c_index = c_index + 1;
SET
	p_risk_data = (
		SELECT
			REPLACE(p_risk_data, CONCAT(str1, "¥"), '')
	);
END WHILE;
INSERT INTO
	`transaction_risk_corporate` (
		`customercode`,
		`customername`,
		`dateofassessment`,
		`createddate`,
		`address`,
		`Customer_nationality`,
		`risk_sum`,
		`risk_count`,
		`final_risk_score`,
		`risk_score_before_override`,
		`Client_Id`,`assessment_version`,created_by,version,remarks,riskoverride,type,`product_reference`, `product_value`, `comments`,`caseversion`
	)
VALUES
	(
		p_customercode,
		p_customername,
		p_dateofassessment,
		CURRENT_TIMESTAMP,
		p_address,
		p_Customer_nationality,
		p_risk_sum,
		p_risk_count,
		p_final_risk_score,
		p_risk_score_before_override,
		p_clientId,c_assessment_version,p_created_by,p_version,p_remarks,p_riskoverride,p_type,p_product_reference, p_product_value, p_comments,p_caseVersion
	);
SELECT
	LAST_INSERT_ID();
END ;;
DELIMITER ;
