CREATE  PROCEDURE `ins_user`(
IN p_fname varchar(250),
IN p_lname varchar(250),
IN p_code varchar(100),
IN p_username varchar(200),
IN p_password varchar(250),
IN p_remarks varchar(1000),
IN p_designation_id int,
IN p_department_id int,
IN p_user_group_id int,
IN p_branch_id int,
IN p_country_id int,
IN p_identity_type_id int,
IN p_is_active int,
IN p_is_deleted int,
IN p_is_blocked int,
IN p_created_by INT,
IN p_clientId INT
)
BEGIN
DECLARE p_user_id int default 0;
IF EXISTS (SELECT user_name FROM user WHERE user_name = p_username AND Client_Id = p_clientId)
then
SELECT null;
else
INSERT INTO `user` (`fname`, `lname`,`emp_code`,`user_name`,`password`,`remarks`,`designation_id`,`department_id`,`user_group_id`,`branch_id`,`country_id`,`identity_type_id`,`is_active`,`is_deleted`,`is_blocked`,`created_by`,`Client_Id`)
VALUES (p_fname, p_lname, p_code,p_username,MD5(p_password),p_remarks,p_designation_id,p_department_id,p_user_group_id,p_branch_id,p_country_id,p_identity_type_id,p_is_active,p_is_deleted,p_is_blocked,p_created_by,p_clientId);
SELECT last_insert_id();
set p_user_id = (SELECT last_insert_id());
INSERT INTO user_password_history (UserId, UserName, Password, UpdatedBy, UpdatedOn)
    values (p_user_id, p_username,  MD5(p_password), p_created_by, NOW());
end if;
END ;;
DELIMITER ;
