CREATE  PROCEDURE `mod_client`(
    IN p_id INT,
    IN p_Client_Name VARCHAR(255),
    IN p_Prefix VARCHAR(50),
    IN p_C6Username VARCHAR(100),
    IN p_C6Threshold INT,
    IN p_Threshold INT,
    IN p_description TEXT,
    IN p_updatedBy INT,
    IN p_complem VARCHAR(255),
    IN p_C6BaseUrl VARCHAR(255),
    IN p_ApplicationStartDate DATETIME,
    IN p_ApplicationEndDate DATETIME,
    IN p_SearchCount INT
)
BEGIN
    UPDATE client_master
    SET Client_Name = p_Client_Name,
        Prefix = p_Prefix,
        C6Username = p_C6Username,
        C6Threshold = p_C6Threshold,
        Threshold = p_Threshold,
        Description = p_description,
        catogory_value = p_complem,
        C6BaseUrl = p_C6BaseUrl,
        ApplicationStartDate = p_ApplicationStartDate,
        ApplicationEndDate = p_ApplicationEndDate,
        searchcount = p_SearchCount
    WHERE Client_Id = p_id;
    SELECT ROW_COUNT();
END ;;
DELIMITER ;
