CREATE  PROCEDURE `mod_corporate_kyc`(
IN p_customer_id VARCHAR(200),
IN p_entity_type VARCHAR(200),
IN p_entity_city VARCHAR(200),
IN p_entity_emirate VARCHAR(200),
IN p_enitity_country VARCHAR(200),
IN p_po_box VARCHAR(50),
IN p_corporate_website VARCHAR(50),
IN p_email VARCHAR(50),
IN p_license_issue_date VARCHAR(50),
IN p_license_authority VARCHAR(200),
IN p_license_expiry_date VARCHAR(50),
IN p_place_of_issue VARCHAR(50),
IN p_license_type VARCHAR(50),
IN p_vat_number VARCHAR(50),
IN p_fund_source VARCHAR(200),
IN p_fund_source_other VARCHAR(200),
IN p_business_type VARCHAR(200),
IN p_pep_status INT,
IN p_pep_name VARCHAR(50),
IN p_pep_title VARCHAR(50),
IN p_pep_type_status INT,
IN p_product_type VARCHAR(200),
IN p_delivery_channel VARCHAR(200),
IN p_remark VARCHAR(1450)
)
BEGIN
DECLARE c_updated_version INT;
SET c_updated_version=(SELECT VERSION FROM corporate_kyc WHERE customer_id= p_customer_id)+1;
UPDATE corporate_kyc
SET
`entity_type`=p_entity_type  ,
`country`= p_enitity_country,
`emirate`=p_entity_emirate ,
`city`= p_entity_city,
`po_box`=p_po_box ,
`corporate_website`=p_corporate_website ,
`email`= p_email,
`license_issue_date`=p_license_issue_date ,
`license_issuing_authority`= p_license_authority,
`license_expiry_date`=p_license_expiry_date ,
`place_of_issue`= p_place_of_issue,
`license_type`=p_license_type ,
`vat_number`=p_vat_number ,
`fund_source`=p_fund_source ,
`fund_source_other`= p_fund_source_other,
`business_type`=p_business_type ,
`pep_status`=p_pep_status ,
`pep_name`= p_pep_name,
`pep_title` = p_pep_title,
`pep_type_status`= p_pep_type_status,
`product_type`= p_product_type,
`delivery_channel`=p_delivery_channel ,
`remark`= p_remark,
version=c_updated_version
WHERE
customer_id=p_customer_id;
END ;;
