CREATE  PROCEDURE `mod_digiapiuser_by_username`(
IN p_username varchar(250),
IN p_api_name varchar(250),
IN p_company_id varchar(250),
IN p_password varchar(250),
IN p_userid INT,
IN p_token varchar(5000)
)
BEGIN
 if exists(SELECT token from `digiapiuser`
 where username = p_username) THEN
 begin
 UPDATE `digiapiuser`
 SET token = p_token
 where username = p_username;
 end;
 else
 begin
 INSERT INTO `digiapiuser`
 (
 `api_name`,
 `company_id`,
 `token`,
 `company_id`,
 `userid`,
 `created_on`,
 `password`
 )
 VALUES
 (
 p_api_name,
 p_company_id,
 p_token,
 p_company_id,
 p_userid,
 NOW(),
 p_password
 );
 end;
 end if;
END ;;
