/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `mod_monitor_status`(
	IN p_ids VARCHAR(15000),
  IN p_status INT
)
BEGIN
	DECLARE _next TEXT DEFAULT NULL;
	DECLARE _nextlen INT DEFAULT NULL;
	DECLARE _value TEXT DEFAULT NULL;
	DECLARE tranrefno VARCHAR(50);
	iterator: LOOP
		IF CHAR_LENGTH(TRIM(p_ids)) = 0 OR p_ids IS NULL THEN
			LEAVE iterator;
		END IF;
		SET _next = SUBSTRING_INDEX(p_ids, ',', 1);
		SET _nextlen = CHAR_LENGTH(_next);
		SET _value = TRIM(_next);
		UPDATE
		  transactionmonitor
		SET
		  tmsstatus = p_status
		WHERE
      id = _value;
    SELECT TranRefNo INTO tranrefno FROM transactionmonitor WHERE id = _value;
    CALL tms_update_score(tranrefno);
		SET p_ids = INSERT (p_ids, 1, _nextlen + 1, '');
	END LOOP;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
