CREATE  PROCEDURE `sel_customermaster_paginated`(
            _PageIndex INT,
            _PageSize INT,
            sortCol TEXT,
            sortOrder TEXT,
            IN filterTxt TEXT,
            IN c_clientId INT
        )
BEGIN
            SET @where_clause = CONCAT(' where cm.Client_Id = ',c_clientId, ' AND cc.is_deleted = 0 AND cm.is_deleted = 0');
            SET @sort_clause = CONCAT(' ORDER BY ',sortCol,' ',sortOrder);
            DROP TEMPORARY TABLE IF EXISTS temp_customermaster;
            CALL `exec_query` (CONCAT('CREATE TEMPORARY TABLE IF NOT EXISTS temp_customermaster AS
                (SELECT cm.`id`,
                    cm.`cust_ref_id`,
                    cm.`fname`,
                    cm.`mname`,
                    cm.`lname`,
                    cm.`dob`,
                    cm.`nationality`,
                    CASE WHEN cm.`cust_type` = ''I''
                        THEN ''INDIVIDUAL''
                    WHEN cm.`cust_type` = ''C''
                        THEN ''CORPORATE''
                    WHEN cm.`cust_type` = ''S''
                        THEN ''SHAREHOLDER''
                    ELSE ''''
                END AS cust_type,
                    cm.`cust_id_type`,
                    cm.`cust_id_number`,
                    cm.`mobile`,
                    cm.`batch_id`,
                    cm.`is_deleted`,
                    cm.`status`,
                    cm.`created_by`,
                    cm.`created_on`,
                    cm.`updated_by`,
                    cm.`updated_on`,
                    cm.`customer_final_risk_score`,
                    cm.`customer_screen_match_score`,
                    cm.`whitelisted_for_screening`
                FROM `customermaster` cm
                INNER JOIN customercase cc ON cm.id = cc.cust_master_id',
                @where_clause,
                @sort_clause,
                ')'));
            SET @RowNumber:=0;
            DROP TEMPORARY TABLE IF EXISTS temp_customermasters;
            CREATE TEMPORARY TABLE IF NOT EXISTS temp_customermasters AS
            (

                    SELECT *, @RowNumber:=@RowNumber+1 RowNumber FROM temp_customermaster
                WHERE (CASE WHEN LENGTH(IFNULL(filterTxt,'')) > 0 THEN
                        (replace (CONCAT(CASE
                        WHEN LOWER(temp_customermaster.fname) IS NULL THEN ''
                        ELSE LOWER(temp_customermaster.fname)
                    END,
                    CASE
                        WHEN LOWER(temp_customermaster.mname) IS NULL THEN ''
                        ELSE LOWER(temp_customermaster.mname)
                    END,
                    CASE
                        WHEN LOWER(temp_customermaster.lname) IS NULL THEN ''
                        ELSE LOWER(temp_customermaster.lname)
                    END), " ", '')) LIKE CONCAT('%',replace (LOWER(filterTxt), ' ', ''),'%') OR
                        `nationality` LIKE CONCAT('%',LOWER(filterTxt),'%') OR
                        `cust_ref_id` LIKE CONCAT('%',LOWER(filterTxt),'%')
                    ELSE 1=1 END)
            );
            SET @RecordCount = (SELECT COUNT(id) FROM temp_customermasters);
            SELECT temp_customermasters.*,@RecordCount AS record_count FROM temp_customermasters WHERE RowNumber BETWEEN
            (_PageIndex -1) * _PageSize + 1 AND (((_PageIndex -1) * _PageSize + 1) + _PageSize) - 1;
            DROP TEMPORARY TABLE IF EXISTS temp_customermaster;
            DROP TEMPORARY TABLE IF EXISTS temp_customermasters;
        END ;;
DELIMITER ;
