CREATE  PROCEDURE `sp_CreateProliferationFinanceCase`(
    IN p_CustomerType VARCHAR(50),
    IN p_CorporateId VARCHAR(100),
    IN p_CompanyName VARCHAR(255),
    IN p_HsCode VARCHAR(100),
    IN p_CasNumber VARCHAR(100),
    IN p_Eccn VARCHAR(100),
    IN p_ChemicalName TEXT,
    IN p_SynonymName TEXT,
    IN p_MatchedChemicalName TEXT,
    IN p_Score VARCHAR(50),
    IN p_StatusReason TEXT,
    IN p_Type VARCHAR(50),
    IN p_CreatedBy INT,
    IN p_ClientId INT,
    IN p_SearchHitDetails LONGTEXT,
    OUT p_CaseId INT
)
BEGIN
    DECLARE v_version INT;

    SELECT IFNULL(MAX(Version), 0) + 1 INTO v_version
    FROM proliferationfinancecase
    WHERE CorporateId = p_CorporateId AND Client_Id = p_ClientId;
    INSERT INTO proliferationfinancecase (
        CustomerType, CorporateId, CompanyName, HsCode, CasNumber, Eccn,
        ChemicalName, SynonymName, MatchedChemicalName, Score, StatusReason, Type, CreatedBy, Client_Id,
        SearchHitDetails, Version
    )
    VALUES (
        p_CustomerType, p_CorporateId, p_CompanyName, p_HsCode, p_CasNumber, p_Eccn,
        p_ChemicalName, p_SynonymName, p_MatchedChemicalName, p_Score, p_StatusReason, p_Type, p_CreatedBy, p_ClientId,
        p_SearchHitDetails, v_version
    );
    SET p_CaseId = LAST_INSERT_ID();
    SELECT p_CaseId AS CaseId;
END ;;
DELIMITER ;
