CREATE  PROCEDURE `sp_GetNotepadv2`(
    IN p_client_id INT,
    IN p_search VARCHAR(255)
)
BEGIN
    SELECT n.*,
           CONCAT(u1.fname, ' ', u1.lname) AS createdByName,
           CONCAT(u2.fname, ' ', u2.lname) AS updatedByName
    FROM notepadv2 n
    LEFT JOIN user u1 ON n.created_by = u1.id
    LEFT JOIN user u2 ON n.updated_by = u2.id
    WHERE n.client_id = p_client_id
    AND n.is_delete = 0
    AND (
        p_search IS NULL OR p_search = ''
        OR n.customer_name LIKE CONCAT('%', p_search, '%')
        OR n.wds_cust_id LIKE CONCAT('%', p_search, '%')
        OR n.unit_ref_no LIKE CONCAT('%', p_search, '%')
    )
    ORDER BY n.id DESC;
END ;;
DELIMITER ;
