CREATE  PROCEDURE `sp_SaveNotepadv2`(
    IN p_id INT,
    IN p_date_of_receipt DATE,
    IN p_cust_type VARCHAR(100),
    IN p_wds_cust_id VARCHAR(200),
    IN p_customer_name VARCHAR(500),
    IN p_Comment_kyc VARCHAR(1000),
    IN p_user_id INT,
    IN p_client_id INT,
    IN p_case_type VARCHAR(500),
    IN p_unit_ref_no VARCHAR(200),
    IN p_cust_type_realestate VARCHAR(200),
    IN p_kyc_check VARCHAR(200)
)
BEGIN
    IF p_id = 0 THEN
        INSERT INTO notepadv2 (
            date_of_receipt, cust_type, wds_cust_id, customer_name,
            Comment_kyc, created_by, created_on, client_id,
            case_type, unit_ref_no, cust_type_realestate, kyc_check
        )
        VALUES (
            p_date_of_receipt, p_cust_type, p_wds_cust_id, p_customer_name,
            p_Comment_kyc, p_user_id, NOW(), p_client_id,
            p_case_type, p_unit_ref_no, p_cust_type_realestate, p_kyc_check
        );
        SELECT LAST_INSERT_ID();
    ELSE
        UPDATE notepadv2 SET
            date_of_receipt = p_date_of_receipt,
            cust_type = p_cust_type,
            wds_cust_id = p_wds_cust_id,
            customer_name = p_customer_name,
            Comment_kyc = p_Comment_kyc,
            updated_by = p_user_id,
            updated_on = NOW(),
            case_type = p_case_type,
            unit_ref_no = p_unit_ref_no,
            cust_type_realestate = p_cust_type_realestate,
            kyc_check = p_kyc_check
        WHERE id = p_id;
        SELECT p_id;
    END IF;
END ;;
DELIMITER ;
