/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `sp_SearchUAEControlList`(
    IN p_hs_code VARCHAR(100),
    IN p_cas_number VARCHAR(100),
    IN p_eccn VARCHAR(100),
    IN p_chemical_name TEXT,
    IN p_synonym_name TEXT
)
BEGIN
    SELECT
        Id,
        CasNumber,
        SynonymName,
        HsCode,
        ChemicalName,
        Eccn,
        PhysicalState,
        PermitRequired,
        Description,

        (CASE
            WHEN p_hs_code IS NOT NULL AND HsCode = p_hs_code THEN 100
            WHEN p_cas_number IS NOT NULL AND CasNumber = p_cas_number THEN 100
            WHEN p_eccn IS NOT NULL AND Eccn = p_eccn THEN 100
            WHEN p_chemical_name IS NOT NULL AND ChemicalName = p_chemical_name THEN 95
            WHEN p_chemical_name IS NOT NULL AND ChemicalName LIKE CONCAT(p_chemical_name, '%') THEN 90
            WHEN p_synonym_name IS NOT NULL AND SynonymName = p_synonym_name THEN 85
            WHEN p_chemical_name IS NOT NULL AND ChemicalName LIKE CONCAT('%', p_chemical_name, '%') THEN 80
            WHEN p_synonym_name IS NOT NULL AND SynonymName LIKE CONCAT('%', p_synonym_name, '%') THEN 75
            WHEN p_chemical_name IS NOT NULL AND SOUNDEX(ChemicalName) = SOUNDEX(p_chemical_name) THEN 60
            WHEN p_synonym_name IS NOT NULL AND SOUNDEX(SynonymName) = SOUNDEX(p_synonym_name) THEN 55
            ELSE 30
        END) AS MatchScore
    FROM UAEControlList
    WHERE
        (p_hs_code IS NOT NULL AND p_hs_code <> '' AND HsCode = p_hs_code)
        OR (p_cas_number IS NOT NULL AND p_cas_number <> '' AND CasNumber = p_cas_number)
        OR (p_eccn IS NOT NULL AND p_eccn <> '' AND Eccn = p_eccn)
        OR (p_chemical_name IS NOT NULL AND p_chemical_name <> '' AND (ChemicalName LIKE CONCAT('%', p_chemical_name, '%') OR SOUNDEX(ChemicalName) = SOUNDEX(p_chemical_name)))
        OR (p_synonym_name IS NOT NULL AND p_synonym_name <> '' AND (SynonymName LIKE CONCAT('%', p_synonym_name, '%') OR SOUNDEX(SynonymName) = SOUNDEX(p_synonym_name)))
    ORDER BY MatchScore DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
