CREATE  PROCEDURE `sp_UpdateProliferationFinanceSearchHits`(
    IN p_CaseId INT,
    IN p_HitDetails LONGTEXT
)
BEGIN
    UPDATE ProliferationFinanceCase
    SET SearchHitDetails = p_HitDetails,
        UpdatedOn = CURRENT_TIMESTAMP
    WHERE Id = p_CaseId;
END ;;
