DELIMITER ;;
CREATE  PROCEDURE `verify_duplicate_name`(In p_fullname varchar(500),In p_type varchar(500),In p_clientid int)
BEGIN
    DECLARE v_threshold INT DEFAULT 75;
    DECLARE v_partial_threshold INT DEFAULT 85;
    DECLARE v_input VARCHAR(500);
    DECLARE v_normalized_input VARCHAR(500);
    SET v_input = TRIM(IFNULL(p_fullname, ''));
    SET v_normalized_input = normalize_name(v_input);
    SELECT  `ca`.`id` AS `id`,
            `cu`.`cust_ref_id` AS `customer_master_id`,
            IFNULL(`cu`.`fname`, '') AS `fname`,
            IFNULL(`cu`.`mname`, '') AS `mname`,
            IFNULL(`cu`.`lname`, '') AS `lname`,
            `cu`.`dob` AS `dob`,
            `cu`.`cust_ref_id` AS `cust_id`,
            IFNULL(`cu`.`nationality`, '') AS `nationality`,
            IFNULL(`ca`.`comments`, '') AS `comments`,
            IFNULL(`ca`.`risk_score`, 0) AS `risk_score`,
            IFNULL(GREATEST(
                levenshtein_ratio(LOWER(v_input), LOWER(IFNULL(cu.fname, ''))),
                levenshtein_ratio(LOWER(v_input), LOWER(IFNULL(cu.lname, ''))),
                levenshtein_ratio(LOWER(v_input), LOWER(CONCAT(IFNULL(cu.fname, ''), ' ', IFNULL(cu.lname, '')))),
                levenshtein_ratio(v_normalized_input, normalize_name(IFNULL(cu.fname,''))),
                levenshtein_ratio(v_normalized_input, normalize_name(IFNULL(cu.lname,''))),
                levenshtein_ratio(v_normalized_input, normalize_name(CONCAT(IFNULL(cu.fname,''),' ',IFNULL(cu.lname,''))))
            ), 0) AS `match_score`,
            `cu`.`batch_id` AS `batch_id`,
            IFNULL(`cu`.`mobile`, '') AS `mobile`,
            `cu`.`cust_type` AS `cust_type`,
            IFNULL(`cu`.`cust_id_type`, '') AS `customer_id_type`,
            IFNULL(`cu`.`cust_id_number`, '') AS `customer_id_number`,
             `ca`.`status` AS `status`,
            CASE ca.status
                WHEN 0 THEN 'Pending'
                WHEN 1 THEN 'Assigned'
                WHEN 2 THEN 'Approved'
                WHEN 3 THEN 'Rejected'
                WHEN 4 THEN 'Pending with Senior Management'
                WHEN 5 THEN 'Auto'
                WHEN 6 THEN 'Pending Case Created from Daily Scheduler'
                ELSE '-'
            END AS 'CaseStatus',
            IFNULL(`ca`.`source`, '') AS `source`,
            IFNULL(`ca`.`match_category`, '') AS `match_category`,
            IFNULL(`ca`.`match_type`, '') AS `match_type`,
            `ca`.`created_by` AS `created_by`,
            `ca`.`created_on` AS `created_on`,
            `ca`.`updated_by` AS `updated_by`,
            `ca`.`updated_on` AS `updated_on`,
            IFNULL(`ca`.`source_unique_id`, '') AS `source_unique_id`,
            `ca`.`is_deleted` AS `is_deleted`,
            (SELECT CONCAT(IFNULL(`fname`, ''), ' ', IFNULL(`lname`, '')) FROM `user` `u` WHERE `u`.`id` = `ca`.`created_by`) AS `created_user`,
            IFNULL(`ca`.`is_matched`, 0) AS `is_matched`,IFNULL(cu.company_code,'N/A') AS `company_code`,
            IFNULL(cu.tradelicense,'N/A') AS tradelicense,
             cu.type
            From
     customercase ca
                INNER JOIN
            customermaster cu ON cu.id = ca.cust_master_id
    WHERE ca.client_id=p_clientid and cu.cust_type= p_type AND (
                v_input = ''
             OR cu.fname COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', v_input, '%') COLLATE utf8mb4_0900_ai_ci
             OR cu.lname COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', v_input, '%') COLLATE utf8mb4_0900_ai_ci

             OR levenshtein_ratio(LOWER(v_input COLLATE utf8mb4_0900_ai_ci), LOWER(CONCAT(IFNULL(cu.fname, ''), ' ', IFNULL(cu.lname, '') COLLATE utf8mb4_0900_ai_ci))) >= v_threshold

             OR levenshtein_ratio(v_normalized_input COLLATE utf8mb4_0900_ai_ci, normalize_name(CONCAT(IFNULL(cu.fname,''),' ',IFNULL(cu.lname,''))COLLATE utf8mb4_0900_ai_ci)) >= v_threshold

             OR SOUNDEX(v_input COLLATE utf8mb4_0900_ai_ci) = SOUNDEX(CONCAT(IFNULL(cu.fname,''),' ',IFNULL(cu.lname,'') COLLATE utf8mb4_0900_ai_ci))

             OR (

                   SOUNDEX(v_input COLLATE utf8mb4_0900_ai_ci) = SOUNDEX(SUBSTRING_INDEX(TRIM(cu.fname), ' ', 1)COLLATE utf8mb4_0900_ai_ci)
                OR SOUNDEX(v_input COLLATE utf8mb4_0900_ai_ci) = SOUNDEX(SUBSTRING_INDEX(SUBSTRING_INDEX(TRIM(cu.fname), ' ', 2), ' ', -1)COLLATE utf8mb4_0900_ai_ci)
                OR SOUNDEX(v_input COLLATE utf8mb4_0900_ai_ci) = SOUNDEX(SUBSTRING_INDEX(SUBSTRING_INDEX(TRIM(cu.fname), ' ', 3), ' ', -1) COLLATE utf8mb4_0900_ai_ci)

                OR levenshtein_ratio(LOWER(v_input COLLATE utf8mb4_0900_ai_ci), LOWER(SUBSTRING_INDEX(TRIM(cu.fname), ' ', 1)COLLATE utf8mb4_0900_ai_ci)) >= v_partial_threshold
                OR levenshtein_ratio(LOWER(v_input COLLATE utf8mb4_0900_ai_ci), LOWER(SUBSTRING_INDEX(SUBSTRING_INDEX(TRIM(cu.fname), ' ', 2), ' ', -1) COLLATE utf8mb4_0900_ai_ci)) >= v_partial_threshold
             )
             OR (

                   SOUNDEX(v_input COLLATE utf8mb4_0900_ai_ci) = SOUNDEX(SUBSTRING_INDEX(TRIM(cu.lname), ' ', 1) COLLATE utf8mb4_0900_ai_ci)
                OR SOUNDEX(v_input COLLATE utf8mb4_0900_ai_ci) = SOUNDEX(SUBSTRING_INDEX(SUBSTRING_INDEX(TRIM(cu.lname), ' ', 2), ' ', -1)COLLATE utf8mb4_0900_ai_ci)
                OR levenshtein_ratio(LOWER(v_input), LOWER(SUBSTRING_INDEX(TRIM(cu.lname), ' ', 1) COLLATE utf8mb4_0900_ai_ci)) >= v_partial_threshold
             )
            )
            ORDER BY match_score DESC;
END ;;
DELIMITER ;
